-- Preguntas
on conflict (id) do update set module_id = excluded.module_id, submodule_id = excluded.submodule_id, prompt = excluded.prompt, correct_answer = excluded.correct_answer, distractors = excluded.distractors, is_boss_final = excluded.is_boss_final, sort_order = excluded.sort_order;
-- Las respuestas siguen a su pregunta si esta cambió de módulo.
update public.answers a set module_id = q.module_id from public.questions q where q.id = a.question_id and a.module_id <> q.module_id;

