insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m1-s1', 'm1-s1', 'Textura y Estructura del Suelo', '[{"heading":"Textura: la huella mineral","body":["La textura es la proporción de arena, limo y arcilla en la tierra fina (partículas menores a 2 mm). Según el USDA, la arena mide entre 2 y 0,05 mm, el limo entre 0,05 y 0,002 mm y la arcilla menos de 0,002 mm.","Con esos porcentajes se ubica el suelo en el triángulo textural, que define 12 clases (arenosa, franca, franco-arcillosa, arcillosa, etc.). La textura condiciona la retención de agua, la aireación, la CIC y la facilidad de laboreo.","A escala agronómica la textura no cambia con el manejo: es una propiedad heredada del material parental y de la meteorización. Por eso se maneja en torno a ella, no contra ella."]},{"heading":"Cómo se mide: el método de Bouyoucos","body":["Se dispersa la muestra con hexametafosfato de sodio y agitación, para separar los agregados en partículas individuales, y se lleva a una probeta con agua.","Las partículas sedimentan según la Ley de Stokes: las más grandes caen más rápido. A los 40 segundos la arena ya decantó, así que el hidrómetro mide limo + arcilla en suspensión; a las 2 horas solo queda arcilla en suspensión.","El método de la pipeta es la referencia de laboratorio. En terreno, el \"tacto\" (formar una cinta con la muestra húmeda) permite una estimación rápida."]},{"heading":"Estructura: la arquitectura del suelo","body":["La estructura es la forma en que las partículas se agrupan en agregados (peds). Los cementan arcillas, materia orgánica, óxidos de Fe y Al, el calcio (floculante) y la biología: raíces, hifas y la glomalina de los hongos micorrícicos.","Tipos principales: granular (típica de horizontes A con buena MO), bloques angulares y subangulares, prismática, columnar (asociada a suelos sódicos) y laminar (frecuente por compactación). Sin estructura: grano simple (arenas) o masiva.","El grado (débil, moderado, fuerte) indica qué tan definidos y estables son los agregados."]},{"heading":"Estabilidad y manejo","body":["El sodio intercambiable (PSI alto) dispersa las arcillas: el suelo se sella, forma costras y estructura columnar. El calcio, por ejemplo aplicado como yeso, flocula y ayuda a recuperarlo.","La labranza excesiva y el tránsito con suelo húmedo destruyen agregados; la materia orgánica, las raíces vivas y los cultivos de cobertura los estabilizan.","La estabilidad de agregados se evalúa con tamizado en húmedo: más agregados estables significa mejor infiltración y menos erosión."]}]'::jsonb, null, null, '[{"id":"m1-s1-cp1","timestamp_seconds":95,"prompt":"En el método de Bouyoucos, ¿qué estima la lectura del hidrómetro a los 40 segundos?","options":["Solo la arcilla en suspensión","El limo + la arcilla en suspensión","La arena en suspensión","La materia orgánica disuelta"],"correct_index":1,"explanation":"Por la Ley de Stokes la arena decanta en unos 40 s; lo que sigue suspendido es limo + arcilla. La lectura de 2 horas estima solo la arcilla."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m1-s2', 'm1-s2', 'Retención de Agua y Curvas de Humedad', '[{"heading":"El agua retenida y el potencial mátrico","body":["El suelo retiene agua por adhesión a las superficies de las partículas y por capilaridad en los poros. Mientras más seco está, con más fuerza la retiene: esa fuerza se expresa como potencial mátrico (negativo), en kPa o bar.","Los poros grandes se vacían primero y a tensiones bajas; los poros finos (típicos de suelos arcillosos) retienen agua a tensiones muy altas."]},{"heading":"Los puntos de referencia","body":["Saturación: todos los poros llenos de agua. Capacidad de Campo (CC): humedad tras drenar el exceso por gravedad, asociada a unos −33 kPa (−1/3 bar); en suelos arenosos se usa a menudo −10 kPa.","Punto de Marchitez Permanente (PMP): humedad a unos −1.500 kPa (−15 bar), donde la mayoría de los cultivos ya no recupera la turgencia.","Agua disponible (AD) = CC − PMP. Los suelos arcillosos tienen la CC y el PMP más altos; los francos y franco-limosos suelen tener la mayor agua disponible; los arenosos, la menor."]},{"heading":"La curva característica de humedad","body":["La curva relaciona el contenido volumétrico de agua (θ) con el potencial mátrico. Se obtiene en laboratorio con ollas y placas de presión de Richards: muestras saturadas se someten a presiones conocidas (por ejemplo 0,33 y 15 bar) hasta equilibrar y se mide el agua retenida.","La curva presenta histéresis: a un mismo potencial, el suelo que se está secando retiene más agua que el que se está humedeciendo."]},{"heading":"De la curva al riego","body":["Lámina de agua disponible: AD (mm) = (θCC − θPMP) × profundidad de raíces (mm). Ejemplo: θCC 30 %, θPMP 15 % y raíces a 600 mm dan 0,15 × 600 = 90 mm.","No se espera a llegar al PMP: se riega al alcanzar el agotamiento permisible, típicamente 30 a 50 % del AD según el cultivo. Con 50 % en el ejemplo, se reponen 45 mm.","Los tensiómetros miden en terreno entre 0 y unos −80 kPa: el rango útil para programar el riego de la mayoría de los frutales y hortalizas."]}]'::jsonb, null, null, '[{"id":"m1-s2-cp1","timestamp_seconds":140,"prompt":"Un suelo tiene θCC = 32 % y θPMP = 17 % (volumétrico) y raíces hasta 50 cm. ¿Cuánta agua disponible total retiene?","options":["75 mm","150 mm","7,5 mm","245 mm"],"correct_index":0,"explanation":"AD = (0,32 − 0,17) × 500 mm = 0,15 × 500 = 75 mm."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m1-s3', 'm1-s3', 'Aireación y Compactación', '[{"heading":"Densidad y porosidad","body":["La densidad aparente (Da) incluye los poros; la densidad real (Dr) considera solo los sólidos y en suelos minerales ronda 2,65 g/cm³. La porosidad total se estima como 1 − Da/Dr.","Valores típicos de Da: suelos arenosos 1,5–1,6 g/cm³; francos 1,3–1,4; arcillosos 1,1–1,3. Los Andisoles (trumaos) pueden bajar de 0,9 g/cm³.","Los macroporos drenan y airean; los microporos retienen agua. Un buen suelo agrícola combina ambos."]},{"heading":"Aireación: las raíces también respiran","body":["Las raíces y la biota consumen O₂ y liberan CO₂; el intercambio ocurre por difusión a través de los poros con aire.","Se considera que bajo un 10 % de porosidad de aire (a capacidad de campo) aparece hipoxia: menor absorción de agua y nutrientes, más enfermedades de raíz y pérdidas de N por desnitrificación."]},{"heading":"Compactación","body":["La compactación aumenta la Da, elimina macroporos y eleva la resistencia mecánica. Sus causas principales son el tránsito de maquinaria y el pisoteo, sobre todo con el suelo húmedo, cerca de capacidad de campo, cuando es más deformable.","El pie de arado es una capa compactada que se forma justo bajo la profundidad de labranza cuando se labra siempre a la misma profundidad.","Umbrales orientativos que restringen raíces: Da cercana a 1,6 g/cm³ en suelos francos, 1,45–1,5 en arcillosos y 1,75–1,8 en arenosos. Con penetrómetro de cono, sobre 2 MPa el crecimiento radicular se reduce fuertemente."]},{"heading":"Recuperación","body":["Subsolar solo con el suelo friable o seco, para fracturar la capa en vez de amasarla; luego proteger el resultado con tránsito controlado (siempre por las mismas huellas).","Los cultivos de cobertura con raíz pivotante (como el rábano forrajero) funcionan como \"subsolado biológico\", y la materia orgánica mejora la resiliencia del suelo."]}]'::jsonb, null, null, '[{"id":"m1-s3-cp1","timestamp_seconds":180,"prompt":"Un penetrómetro marca 2,8 MPa a 25 cm en la entrehilera de un huerto. ¿Qué significa?","options":["El suelo está bien aireado","Hay una capa compactada que limita el crecimiento de raíces","Falta agua y hay que regar más","El suelo tiene alta materia orgánica"],"correct_index":1,"explanation":"Sobre ~2 MPa la resistencia mecánica restringe fuertemente las raíces: es una capa compactada (por ejemplo, pie de arado o huella de tránsito)."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m1-s4', 'm1-s4', 'Erosión y Conservación de Suelos', '[{"heading":"El proceso: desprender, transportar, depositar","body":["La erosión hídrica comienza con el impacto de la gota de lluvia, que desprende partículas (salpicadura) y sella la superficie. Luego el escurrimiento las transporta y las deposita aguas abajo.","Formas: laminar (pérdida pareja y poco visible), en surcos o regueros (canales pequeños que la labranza borra) y cárcavas (canales profundos que la labranza normal no puede cruzar ni borrar).","La erosión eólica mueve partículas por reptación, saltación y suspensión; es mayor en suelos secos, sueltos y sin cobertura."]},{"heading":"Estimar la pérdida: la USLE","body":["La Ecuación Universal de Pérdida de Suelo estima la pérdida media anual: A = R · K · LS · C · P.","R es la erosividad de la lluvia; K, la erodabilidad del suelo (mayor en suelos limosos o de arenas muy finas con poca materia orgánica); LS, el largo y la inclinación de la pendiente; C, la cobertura y el manejo; P, las prácticas de conservación.","R, K y LS dependen del lugar; el agricultor actúa sobre C y P."]},{"heading":"La erosión en Chile","body":["Según estudios de CIREN, cerca de la mitad del territorio nacional presenta algún grado de erosión, con situaciones críticas en el secano costero e interior de la zona central.","La combinación de lluvias concentradas en invierno, laderas sin cobertura y suelos degradados acelera la pérdida de la capa arable, que tarda siglos en formarse."]},{"heading":"Prácticas de conservación","body":["Cobertura: cultivos de cobertura, mulch, rastrojos y cero labranza (bajan el factor C).","Prácticas mecánicas: cultivo en contorno, fajas, terrazas, zanjas de infiltración y control de cárcavas con diques (bajan el factor P).","Contra el viento: cortinas cortaviento y mantener el suelo cubierto."]}]'::jsonb, null, null, '[{"id":"m1-s4-cp1","timestamp_seconds":210,"prompt":"En la USLE, sembrar una cubierta vegetal entre hileras reduce principalmente el factor…","options":["R (erosividad de la lluvia)","K (erodabilidad del suelo)","C (cobertura y manejo)","LS (topografía)"],"correct_index":2,"explanation":"La cobertura protege del impacto de la gota y frena el escurrimiento: actúa sobre el factor C, que depende del manejo."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m1-s5', 'm1-s5', 'Horizontes y Perfil de Suelo', '[{"heading":"La calicata","body":["Una calicata es un hoyo de observación de aproximadamente 1 × 1,5 m y 1,2 a 1,5 m de profundidad (o hasta la roca). Se describe la cara mejor iluminada, desde la superficie hacia abajo.","Se registran: límites y espesor de cada horizonte, color Munsell (matiz, valor y croma), textura al tacto, estructura, consistencia, raíces, poros, moteados, gravas y reacción al HCl (presencia de carbonatos)."]},{"heading":"Horizontes maestros","body":["O: orgánico, de restos vegetales. A: mineral con materia orgánica acumulada, más oscuro. E: de eluviación, lavado de arcilla, hierro o MO, más claro. B: de acumulación o alteración (Bt arcilla iluvial, Bw cambio de color o estructura, Bk carbonatos, Bn sodio). C: material parental poco alterado. R: roca.","Los sufijos agregan detalle: p (alterado por arado, como en Ap), g (gleyzación por saturación de agua), t (arcilla iluvial), k (carbonatos), n (sodio)."]},{"heading":"Factores formadores","body":["Jenny resumió la formación del suelo como función de cinco factores: clima, organismos, relieve, material parental y tiempo.","Los moteados grises y anaranjados indican saturación de agua y condiciones reductoras alternadas con oxidación: drenaje imperfecto. Son clave para decidir drenaje y especies."]},{"heading":"Suelos de Chile","body":["Andisoles (trumaos) del centro-sur, formados de cenizas volcánicas: arcillas amorfas alofana e imogolita, baja Da, alta retención de agua, alta MO y fuerte fijación de fósforo.","Ñadis: andisoles hidromórficos con una capa cementada de fierrillo que impide el drenaje. Suelos rojos arcillosos (Alfisoles y Ultisoles) en el secano y la precordillera; Mollisoles en el valle central; Aridisoles y Entisoles en el norte."]}]'::jsonb, null, null, '[{"id":"m1-s5-cp1","timestamp_seconds":160,"prompt":"En la calicata aparece a 60 cm un horizonte gris con manchas anaranjadas. ¿Qué indica?","options":["Acumulación de carbonatos","Saturación de agua prolongada (drenaje imperfecto)","Un horizonte orgánico enterrado","Contaminación por fertilizantes"],"correct_index":1,"explanation":"El gris (gleyzación) y los moteados anaranjados reflejan condiciones reductoras alternadas con oxidación del hierro: el suelo pasa largos periodos saturado."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m2-s1', 'm2-s1', 'Capacidad de Intercambio Catiónico', '[{"heading":"Los coloides: superficie con carga","body":["Las arcillas y el humus son coloides: partículas diminutas, de enorme superficie específica y con carga eléctrica, casi siempre negativa. Sobre esa carga se adsorben cationes como Ca²⁺, Mg²⁺, K⁺, Na⁺, NH₄⁺, H⁺ y Al³⁺.","La carga puede ser permanente, por sustitución isomórfica dentro de la red de la arcilla (montmorillonita, vermiculita), o variable, dependiente del pH, como en el humus, los óxidos y las arcillas alofánicas de los Trumaos."]},{"heading":"La CIC y la saturación de bases","body":["La CIC es la cantidad total de cationes que el suelo puede retener e intercambiar, expresada en cmol(+)/kg. Un suelo arenoso pobre en materia orgánica puede tener menos de 5; uno arcilloso o rico en humus, más de 25. El humus aporta entre 150 y 300 cmol(+)/kg, la caolinita apenas 3 a 15.","La saturación de bases es el porcentaje de la CIC ocupado por Ca, Mg, K y Na. Una saturación alta indica un suelo poco ácido y bien provisto; una baja indica que H⁺ y Al³⁺ dominan el complejo de intercambio.","En un suelo agrícola equilibrado el Ca suele ocupar 60-80 % de la CIC, el Mg 10-20 % y el K 2-6 %."]},{"heading":"Por qué importa en el manejo","body":["Una CIC baja significa poca \"memoria\" de nutrientes: conviene fertilizar en dosis fraccionadas, porque el exceso se pierde por lixiviación. Una CIC alta amortigua cambios de pH y retiene mejor el potasio y el amonio.","Los aniones como el nitrato (NO₃⁻) no se retienen en la CIC y se mueven con el agua; el fosfato, en cambio, se fija químicamente a óxidos de Fe y Al o al calcio.","Aumentar la materia orgánica es la forma más efectiva de subir la CIC de un suelo en el mediano plazo."]}]'::jsonb, null, null, '[{"id":"m2-s1-cp1","timestamp_seconds":110,"prompt":"Un suelo arenoso tiene CIC = 4 cmol(+)/kg. ¿Qué estrategia de fertilización potásica conviene?","options":["Una sola dosis alta a la siembra","Dosis fraccionadas durante la temporada","No fertilizar: el K nunca se pierde","Aplicar solo en invierno"],"correct_index":1,"explanation":"Con poca CIC el suelo retiene poco K⁺: una dosis grande se lixivia. Fraccionar ajusta la oferta a la demanda del cultivo."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m2-s2', 'm2-s2', 'pH del Suelo y Encalado', '[{"heading":"El pH y la disponibilidad de nutrientes","body":["El pH es el logaritmo negativo de la actividad de H⁺: un suelo a pH 5 tiene diez veces más acidez activa que uno a pH 6. La mayoría de los cultivos rinde mejor entre pH 6,0 y 7,0, donde la disponibilidad conjunta de nutrientes es mayor.","A pH ácido aumentan la solubilidad del Al, Mn y Fe (con riesgo de toxicidad) y baja la de P, Ca, Mg y Mo. A pH alcalino caen el Fe, Mn, Zn, Cu y B, y el P precipita como fosfatos de calcio."]},{"heading":"Acidez y aluminio en los suelos del sur","body":["Las lluvias abundantes lixivian las bases y acidifican el suelo, proceso que acentúan los fertilizantes amoniacales. Bajo pH 5,5 aparece Al³⁺ intercambiable, que daña el ápice de la raíz y frena su crecimiento.","El indicador clave es la saturación de aluminio: Al intercambiable dividido por la suma de bases más Al. Sobre 5-10 % ya afecta a especies sensibles como alfalfa y cebada; el trigo y la avena son algo más tolerantes.","En Chile, los Andisoles (Trumaos) y Ultisoles (rojo arcillosos) de La Araucanía y Los Lagos son los que más requieren corrección de acidez."]},{"heading":"Encalado","body":["La cal (carbonato de calcio) neutraliza la acidez: el carbonato consume H⁺ y el calcio desplaza al aluminio del complejo de intercambio. La dolomita aporta además magnesio.","La eficacia depende del poder de neutralización (equivalente CaCO₃) y de la finura: las partículas finas reaccionan antes. La cal se mueve poco en el perfil, por lo que debe incorporarse o aplicarse con anticipación al cultivo.","El yeso (sulfato de calcio) no corrige el pH, pero aporta calcio en profundidad y reduce la toxicidad de aluminio en el subsuelo."]}]'::jsonb, null, null, '[{"id":"m2-s2-cp1","timestamp_seconds":135,"prompt":"Un suelo de pH 5,1 tiene 18 % de saturación de aluminio y se sembrará alfalfa. ¿Qué corresponde?","options":["Aplicar yeso para subir el pH","Encalar con anticipación e incorporar la cal","Aplicar urea para neutralizar el Al","Sembrar sin corrección: la alfalfa tolera el Al"],"correct_index":1,"explanation":"La alfalfa es muy sensible al Al. La cal sube el pH y desplaza el Al³⁺; como se mueve poco, conviene incorporarla antes de sembrar."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m2-s3', 'm2-s3', 'Macronutrientes Primarios', '[{"heading":"Nitrógeno: el más dinámico","body":["La planta absorbe N como nitrato (NO₃⁻) y amonio (NH₄⁺). En el suelo, la materia orgánica se mineraliza a amonio y las bacterias nitrificantes lo oxidan a nitrato, que es móvil.","Las pérdidas principales son la lixiviación de nitratos, la volatilización de amoníaco (urea aplicada en superficie sobre suelo húmedo y caluroso o alcalino) y la desnitrificación en suelos saturados, que libera N₂ y N₂O.","El N es móvil dentro de la planta: su deficiencia produce clorosis primero en las hojas viejas."]},{"heading":"Fósforo: el más inmóvil","body":["El fósforo se absorbe como ortofosfato (H₂PO₄⁻ y HPO₄²⁻). Se mueve muy poco en el suelo: llega a la raíz por difusión, a milímetros de distancia, por lo que la localización del fertilizante y las micorrizas son decisivas.","En suelos ácidos se fija a óxidos de Fe y Al; en los Andisoles la alofana retiene fosfato con mucha fuerza, de modo que exigen dosis altas. En suelos calcáreos precipita como fosfato de calcio.","Su deficiencia retrasa el crecimiento y puede dar tonos púrpura en hojas por acumulación de antocianinas."]},{"heading":"Potasio: el regulador","body":["El K⁺ regula la apertura de estomas, la presión de turgencia, la activación de enzimas y el transporte de azúcares hacia frutos. Se asocia al calibre, color, firmeza y azúcar de la fruta.","Su deficiencia se ve como necrosis en el borde de las hojas viejas (quemado marginal), porque es móvil en la planta.","El cloruro de potasio (muriato) es la fuente más barata, pero el sulfato de potasio es preferible en cultivos sensibles al cloro, como frambuesa, palto o tabaco."]}]'::jsonb, null, null, '[{"id":"m2-s3-cp1","timestamp_seconds":150,"prompt":"Se aplicó urea en superficie sobre un suelo húmedo un día caluroso y no llovió. ¿Qué pérdida es más probable?","options":["Lixiviación de nitratos","Volatilización de amoníaco","Fijación del N por la alofana","Desnitrificación"],"correct_index":1,"explanation":"La ureasa hidroliza la urea a amonio y, en superficie con calor, parte se pierde como NH₃ gaseoso. Incorporarla o regar después reduce la pérdida."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m2-s4', 'm2-s4', 'Nutrientes Secundarios y Micronutrientes', '[{"heading":"Calcio, magnesio y azufre","body":["El calcio forma las paredes celulares (pectatos) y se mueve solo por el xilema con la transpiración: no se redistribuye. Por eso su falta aparece en órganos que transpiran poco, como frutos y ápices: bitter pit en manzana, pudrición apical en tomate, tip burn en lechuga.","El magnesio es el átomo central de la clorofila. Es móvil, así que su deficiencia da clorosis intervenal en hojas viejas. El exceso de K o de amonio compite con su absorción.","El azufre forma aminoácidos (cisteína, metionina). Se absorbe como sulfato y es poco móvil en la planta: su falta amarillea las hojas nuevas, y es frecuente en suelos del sur pobres en materia orgánica."]},{"heading":"Micronutrientes","body":["Se requieren en gramos por hectárea, pero su ausencia limita el rendimiento igual que un macro (Ley del Mínimo). Los principales son Fe, Mn, Zn, Cu, B, Mo, Cl y Ni.","El hierro es inmóvil: su falta da clorosis intervenal en hojas nuevas, típica en suelos calcáreos o alcalinos (clorosis férrica). Se corrige con quelatos estables a pH alto, como Fe-EDDHA.","El boro participa en la germinación del polen y en la cuaja; tiene un rango muy estrecho entre deficiencia y toxicidad, y la toxicidad por B en aguas de riego es un problema en zonas del norte de Chile. El zinc es clave en la síntesis de auxinas: su falta produce hojas pequeñas y entrenudos cortos (roseta)."]},{"heading":"Móviles e inmóviles: la clave del diagnóstico","body":["Si el nutriente es móvil en la planta (N, P, K, Mg), la deficiencia aparece en las hojas viejas, porque la planta lo traslada a los brotes. Si es inmóvil (Ca, S, Fe, Mn, Zn, Cu, B), aparece en hojas nuevas o en frutos.","Este patrón permite una primera hipótesis en terreno, que luego se confirma con análisis foliar."]}]'::jsonb, null, null, '[{"id":"m2-s4-cp1","timestamp_seconds":125,"prompt":"Un parronal en suelo calcáreo muestra hojas nuevas amarillas con nervaduras verdes. ¿Qué deficiencia es la más probable?","options":["Nitrógeno","Magnesio","Hierro","Potasio"],"correct_index":2,"explanation":"Clorosis intervenal en hojas nuevas apunta a un nutriente inmóvil; en suelo calcáreo el sospechoso clásico es el hierro (clorosis férrica)."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m2-s5', 'm2-s5', 'Diagnóstico Nutricional y Fertilización', '[{"heading":"Análisis de suelo y foliar","body":["El análisis de suelo indica lo que el suelo puede ofrecer: pH, materia orgánica, N mineral, P Olsen, K, bases intercambiables, CE y micronutrientes. Su valor depende de un buen muestreo: muchas submuestras por sector homogéneo y a la profundidad de raíces.","El análisis foliar indica lo que la planta efectivamente absorbió. Se compara con rangos de suficiencia y exige respetar el tipo de hoja y la época estandarizados para cada especie: en frutales, normalmente hojas maduras del brote del año en verano."]},{"heading":"Cuánto fertilizar: el balance","body":["La dosis sale de un balance: demanda del cultivo (extracción por tonelada esperada) menos el aporte del suelo, dividido por la eficiencia del fertilizante. Ningún fertilizante se aprovecha al 100 %: la eficiencia del N suele estar entre 40 y 70 %.","Las \"4 R\" resumen la buena práctica: la fuente correcta, en la dosis correcta, en el momento correcto y en el lugar correcto."]},{"heading":"Salinidad y fertirriego","body":["La conductividad eléctrica (CE, en dS/m) mide sales solubles. Cada especie tiene un umbral de CE en el extracto de saturación sobre el cual pierde rendimiento: el frijol y la frutilla son sensibles; la cebada y la remolacha, tolerantes.","Los fertilizantes son sales: el índice salino indica cuánto suben la CE. En suelos o aguas salinas conviene preferir fuentes de bajo índice y regar con una fracción de lavado que arrastre las sales bajo la zona de raíces.","En suelos sódicos el problema no es la CE sino el sodio intercambiable (PSI): se corrige con calcio (yeso) y lavado."]}]'::jsonb, null, null, '[{"id":"m2-s5-cp1","timestamp_seconds":170,"prompt":"El cultivo extrae 150 kg N/ha, el suelo aporta 60 y la eficiencia del fertilizante es 60 %. ¿Cuánto N aplicar?","options":["90 kg/ha","150 kg/ha","210 kg/ha","54 kg/ha"],"correct_index":1,"explanation":"(150 − 60) / 0,6 = 150 kg N/ha. La eficiencia corrige por lo que se pierde o no se aprovecha."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m3-s1', 'm3-s1', 'Radiación Solar y Balance de Energía', '[{"heading":"Onda corta y onda larga","body":["El sol emite radiación de onda corta (0,3 a 3 µm). Cerca de la mitad es radiación fotosintéticamente activa (PAR, 400-700 nm), la que usan las plantas.","La Tierra, las plantas y las nubes, mucho más frías, emiten radiación de onda larga (infrarrojo térmico). En noches despejadas el suelo pierde onda larga hacia el cielo sin que nada la devuelva: así se enfría y se forman las heladas radiativas."]},{"heading":"Albedo y radiación neta","body":["El albedo es la fracción de la radiación de onda corta que una superficie refleja: la nieve fresca refleja 80-90 %, un cultivo verde cerca de 20-25 % y un suelo oscuro y húmedo apenas 10 %.","La radiación neta es lo que queda: onda corta absorbida más onda larga recibida menos onda larga emitida. De día es positiva; de noche, negativa."]},{"heading":"Dónde se va la energía","body":["La radiación neta se reparte entre calor latente (evaporar agua), calor sensible (calentar el aire) y flujo de calor al suelo. Un cultivo bien regado usa la mayor parte en evapotranspirar; un suelo seco calienta el aire.","Por eso un huerto regado está más fresco que un potrero seco, y un suelo húmedo y compacto guarda más calor del día para liberarlo en la noche.","Las mallas sombra y las cubiertas modifican este balance: reducen la onda corta que llega al cultivo y la onda larga que este pierde de noche."]}]'::jsonb, null, null, '[{"id":"m3-s1-cp1","timestamp_seconds":90,"prompt":"¿Por qué una noche despejada y sin viento es la más peligrosa para las heladas?","options":["Porque llega más radiación solar","Porque el suelo pierde onda larga hacia el cielo sin que vuelva","Porque aumenta la humedad relativa","Porque el viento trae aire frío"],"correct_index":1,"explanation":"Sin nubes que devuelvan radiación, la pérdida de onda larga es máxima y el aire en contacto con el suelo se enfría más."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m3-s2', 'm3-s2', 'Temperatura y Sumas Térmicas', '[{"heading":"Grados día","body":["El desarrollo de plantas e insectos se acelera con la temperatura sobre un umbral base. Los grados día (GD) suman cada día la temperatura media menos esa base: con base 10 °C, un día de media 18 °C aporta 8 GD.","Cada fase (emergencia, floración, cosecha) necesita una suma térmica más o menos constante. Por eso los GD predicen fechas de cosecha en maíz o vid, y el momento de control de plagas como la polilla de la manzana (Cydia pomonella)."]},{"heading":"Horas frío y receso","body":["Los frutales caducos entran en endodormancia en otoño y necesitan acumular frío para brotar parejo en primavera. Una hora frío clásica es una hora bajo 7,2 °C.","El modelo Utah (unidades de frío) da peso máximo a temperaturas cercanas a 6-7 °C y resta frío con temperaturas altas. El modelo dinámico (porciones de frío) es hoy el más usado para climas templados como el chileno.","Si el frío no alcanza, la brotación y la floración son tardías y desuniformes. En esos casos se usan compensadores de frío, como la cianamida hidrogenada."]},{"heading":"Temperaturas extremas","body":["Sobre unos 35 °C muchas especies cierran estomas, baja la fotosíntesis y aparecen daños como golpe de sol en frutos. El calor en floración puede reducir la viabilidad del polen y la cuaja.","La temperatura del aire se mide en una garita meteorológica a 1,5-2 m, ventilada y a la sombra; un termómetro al sol puede marcar varios grados más que el aire real."]}]'::jsonb, null, null, '[{"id":"m3-s2-cp1","timestamp_seconds":120,"prompt":"Con temperatura base 10 °C, ¿cuántos grados día aportan tres días de media 14, 16 y 20 °C?","options":["50 GD","20 GD","30 GD","16 GD"],"correct_index":1,"explanation":"(14 − 10) + (16 − 10) + (20 − 10) = 4 + 6 + 10 = 20 GD."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m3-s3', 'm3-s3', 'Heladas y su Control', '[{"heading":"Tipos de helada","body":["La helada radiativa ocurre en noches despejadas y calmas: el suelo pierde onda larga, el aire en contacto se enfría y se forma una inversión térmica, con aire más cálido unos metros arriba. Es la más común en los valles centrales de Chile.","La helada advectiva llega con una masa de aire polar y viento: no hay inversión y el frío afecta toda la columna de aire. Es mucho más difícil de controlar.","La helada blanca deposita escarcha porque el aire alcanza el punto de rocío; la helada negra ocurre con aire seco, sin escarcha visible, y suele ser más dañina porque no libera calor latente."]},{"heading":"Daño y temperatura crítica","body":["El daño ocurre cuando se forma hielo dentro de los tejidos. Cada estado fenológico tiene una temperatura crítica: las flores abiertas y los frutos recién cuajados son más sensibles que las yemas dormidas.","Las tablas de temperaturas críticas suelen indicar el valor que mata al 10 % y al 90 % de los órganos en cada estado."]},{"heading":"Métodos de control","body":["Pasivos: elegir sitios con buen drenaje de aire frío (evitar hondonadas), mantener el suelo húmedo, compacto y sin cubierta vegetal alta para que acumule calor, y elegir variedades de floración tardía.","Activos: los ventiladores (máquinas de viento) mezclan el aire cálido de la inversión con el frío de abajo, y solo sirven en heladas radiativas. La aspersión sobre el follaje libera calor latente al congelarse el agua: debe mantenerse sin interrupción hasta que el hielo se derrita. Los calefactores agregan calor directo.","Si la aspersión se interrumpe o la tasa de agua es baja, la evaporación roba calor y el daño puede ser peor que sin proteger."]}]'::jsonb, null, null, '[{"id":"m3-s3-cp1","timestamp_seconds":160,"prompt":"Se anuncia una helada con viento sur de 20 km/h y cielo despejado. ¿Qué método activo servirá menos?","options":["Aspersión sobre el follaje","Ventiladores (máquinas de viento)","Calefactores","Riego previo del suelo"],"correct_index":1,"explanation":"Con viento la helada es advectiva: no hay inversión térmica con aire cálido arriba, así que los ventiladores no tienen nada que mezclar."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m3-s4', 'm3-s4', 'Humedad, Viento y Evapotranspiración', '[{"heading":"Humedad del aire","body":["La humedad relativa (HR) es el vapor presente respecto del máximo que el aire admite a esa temperatura. Como el máximo sube con la temperatura, la HR baja al mediodía y sube de noche aunque el vapor no cambie.","El déficit de presión de vapor (DPV) es la diferencia entre la presión de vapor de saturación y la real: mide cuánto \"tira\" la atmósfera del agua de la hoja. Un DPV alto aumenta la transpiración y puede cerrar estomas.","El punto de rocío es la temperatura a la que el aire se satura al enfriarse: sirve para anticipar heladas y el mojado de las hojas, que favorece enfermedades."]},{"heading":"ET de referencia","body":["La evapotranspiración de referencia (ET₀) es lo que evapotranspira una pradera de referencia bien regada. La FAO la estandarizó con la ecuación de Penman-Monteith (FAO-56), que usa radiación, temperatura, humedad y viento.","Un método simple es la bandeja de evaporación clase A: la evaporación medida se multiplica por un coeficiente de bandeja (Kp, alrededor de 0,7-0,8) para estimar ET₀."]},{"heading":"Del clima al riego","body":["La evapotranspiración del cultivo es ETc = ET₀ × Kc. El coeficiente de cultivo (Kc) cambia con la fenología: es bajo en la etapa inicial, máximo en pleno desarrollo y baja hacia la madurez.","El viento aumenta la ET porque renueva el aire húmedo junto a la hoja; también daña físicamente brotes y frutos, por eso se usan cortavientos.","Las estaciones meteorológicas de la red agroclimática (Agromet en Chile) publican ET₀ diaria para programar el riego."]}]'::jsonb, null, null, '[{"id":"m3-s4-cp1","timestamp_seconds":140,"prompt":"La ET₀ del día es 6 mm y el Kc del cultivo en plena temporada es 1,1. ¿Cuál es la ETc?","options":["5,5 mm","6,6 mm","7,1 mm","0,18 mm"],"correct_index":1,"explanation":"ETc = ET₀ × Kc = 6 × 1,1 = 6,6 mm/día."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m3-s5', 'm3-s5', 'Clima de Chile y Riesgo', '[{"heading":"Los climas de Chile","body":["El norte es desértico por el Anticiclón del Pacífico Sur y la corriente de Humboldt, que estabilizan la atmósfera; en la costa aparece la camanchaca. El centro tiene clima mediterráneo: lluvias concentradas en invierno y veranos secos, por eso la agricultura depende del riego.","Hacia el sur aumentan las lluvias y disminuye la temperatura; la Patagonia es fría y ventosa. La Cordillera de los Andes guarda el agua como nieve, que alimenta los ríos en primavera y verano."]},{"heading":"El Niño y La Niña","body":["El ENOS (El Niño-Oscilación del Sur) alterna fases cálidas y frías del Pacífico ecuatorial. En la zona central de Chile, El Niño suele traer inviernos más lluviosos y La Niña, inviernos más secos.","Los años secos y fríos también favorecen heladas más frecuentes. Seguir los pronósticos estacionales ayuda a decidir siembras, seguros y uso del agua."]},{"heading":"Sequía y cambio climático","body":["Desde 2010 la zona central vivió una megasequía con déficit de lluvias por más de una década, con menor nieve acumulada y caudales reducidos.","Las tendencias apuntan a menos precipitación y más temperatura en el centro y norte, con la isoterma 0 °C más alta y menos reserva de nieve. Esto desplaza zonas aptas para cultivos hacia el sur.","La adaptación combina riego tecnificado, especies y portainjertos tolerantes, cosecha de agua, seguros agrícolas y monitoreo agroclimático."]}]'::jsonb, null, null, '[{"id":"m3-s5-cp1","timestamp_seconds":150,"prompt":"Se pronostica un invierno con fase La Niña en la zona central. ¿Qué escenario es más probable?","options":["Invierno más lluvioso que lo normal","Invierno más seco y con heladas más frecuentes","Sin efecto sobre las lluvias","Nevazones en la costa del norte"],"correct_index":1,"explanation":"La Niña suele asociarse a inviernos más secos en la zona central, con cielos despejados que favorecen las heladas radiativas."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m4-s1', 'm4-s1', 'Fotosíntesis y Metabolismo del Carbono', '[{"heading":"Fase luminosa y ciclo de Calvin","body":["En los tilacoides del cloroplasto la luz rompe el agua, libera O₂ y genera ATP y NADPH. En el estroma, el ciclo de Calvin usa esa energía para fijar CO₂ en azúcares.","La enzima que fija el CO₂ es la Rubisco, la proteína más abundante del planeta. Su problema: también reacciona con O₂, y esa reacción, la fotorrespiración, desperdicia carbono y energía, sobre todo con calor y estomas cerrados."]},{"heading":"Plantas C3, C4 y CAM","body":["Las C3 (trigo, arroz, papa, la mayoría de los frutales) fijan el CO₂ directamente con la Rubisco; su primer producto tiene 3 carbonos. Sufren más fotorrespiración en climas cálidos.","Las C4 (maíz, caña de azúcar, sorgo y muchas malezas como el pasto bermuda) fijan primero el CO₂ con la PEP carboxilasa en el mesófilo y lo concentran en la vaina del haz (anatomía Kranz). Así casi eliminan la fotorrespiración y usan mejor el agua y el nitrógeno en calor.","Las CAM (cactus, piña, agave) abren estomas de noche, guardan el CO₂ como ácido málico y lo usan de día con los estomas cerrados: máxima eficiencia en el uso del agua."]},{"heading":"Factores limitantes","body":["La fotosíntesis responde a la luz hasta un punto de saturación; bajo el punto de compensación, la respiración consume más de lo que la hoja fija. Las hojas sombreadas del interior de un árbol pueden quedar bajo ese punto.","El CO₂, la temperatura, el agua (vía estomas) y el nitrógeno (gran parte del N de la hoja está en la Rubisco) también limitan la tasa fotosintética."]}]'::jsonb, null, null, '[{"id":"m4-s1-cp1","timestamp_seconds":130,"prompt":"En un verano caluroso y seco, ¿qué cultivo pierde menos carbono por fotorrespiración?","options":["Trigo (C3)","Maíz (C4)","Papa (C3)","Manzano (C3)"],"correct_index":1,"explanation":"El maíz es C4: concentra CO₂ alrededor de la Rubisco en la vaina del haz y casi elimina la fotorrespiración."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m4-s2', 'm4-s2', 'Potencial Hídrico y Transporte de Agua', '[{"heading":"Potencial hídrico","body":["El potencial hídrico (Ψ) mide la energía libre del agua y se expresa en megapascales (MPa). El agua pura libre tiene Ψ = 0; en suelo y plantas los valores son negativos, y el agua siempre fluye de potencial mayor (menos negativo) a menor (más negativo).","Sus componentes son el potencial osmótico (solutos, siempre negativo), el de presión (turgencia, positivo en células vivas; tensión, negativo en el xilema) y el mátrico (adhesión a superficies, relevante en suelos y paredes)."]},{"heading":"El continuo suelo-planta-atmósfera","body":["El agua entra por la raíz, atraviesa la endodermis (la banda de Caspary obliga a pasar por membranas), sube por el xilema y sale por los estomas. La transpiración genera la tensión que tira de la columna de agua: es la teoría de la cohesión-tensión.","El gradiente va de un suelo húmedo (−0,03 MPa) a una atmósfera seca que puede estar bajo −50 MPa. La mayor resistencia está en la raíz y en el paso de líquido a vapor en la hoja."]},{"heading":"Medir el estrés hídrico","body":["La cámara de presión (de Scholander) mide el potencial xilemático: se encierra una hoja cortada y se aplica presión hasta que el agua aflora en el corte. Esa presión iguala la tensión que tenía el xilema.","El potencial de tallo a mediodía, con la hoja embolsada para detener la transpiración, es el indicador más usado para riego en frutales y vides. El potencial antes del amanecer refleja el agua del suelo que explora la raíz.","Otras herramientas son los dendrómetros (contracción diaria del tronco) y la termografía infrarroja (hojas estresadas se calientan)."]}]'::jsonb, null, null, '[{"id":"m4-s2-cp1","timestamp_seconds":145,"prompt":"Una vid mide −0,6 MPa de potencial de tallo y otra −1,4 MPa a la misma hora. ¿Cuál tiene más estrés hídrico?","options":["La de −0,6 MPa","La de −1,4 MPa","Ambas igual","No se puede saber con el potencial"],"correct_index":1,"explanation":"Un potencial más negativo significa más tensión en el xilema, es decir, más estrés hídrico."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m4-s3', 'm4-s3', 'Estomas y Transpiración', '[{"heading":"El dilema del estoma","body":["Para fijar CO₂ la hoja debe abrir los estomas, pero por el mismo poro sale vapor de agua. Una planta C3 transpira cientos de litros de agua por cada kilo de materia seca que produce.","La transpiración no es solo pérdida: enfría la hoja, mueve los nutrientes disueltos por el xilema (incluido el calcio) y mantiene la tensión que sube el agua."]},{"heading":"Cómo se abren y cierran","body":["Dos células oclusivas rodean el poro. Cuando acumulan K⁺ y solutos, entra agua, se hinchan y el poro se abre. La luz azul, el CO₂ interno bajo y la humedad favorecen la apertura.","El ácido abscísico (ABA), producido cuando el suelo se seca, provoca la salida de K⁺ y el cierre del estoma. El DPV alto, el calor extremo y el CO₂ interno alto también los cierran."]},{"heading":"Uso eficiente del agua","body":["La eficiencia en el uso del agua (EUA) es el carbono fijado por unidad de agua transpirada. Es mayor en plantas CAM, luego C4 y menor en C3.","El riego deficitario controlado (RDC) aprovecha que un estrés moderado en fases poco sensibles reduce el crecimiento vegetativo sin afectar mucho la producción, ahorrando agua y mejorando la calidad, por ejemplo en vides para vino.","El secado parcial de raíces (PRD) alterna el riego entre ambos lados del árbol: las raíces del lado seco envían ABA y la planta cierra parcialmente estomas mientras sigue hidratada."]}]'::jsonb, null, null, '[{"id":"m4-s3-cp1","timestamp_seconds":110,"prompt":"El suelo comienza a secarse y la hoja aún está turgente, pero los estomas ya se cierran. ¿Qué señal lo explica?","options":["Más auxina en la hoja","ABA enviado desde las raíces","Exceso de luz azul","Aumento de giberelinas"],"correct_index":1,"explanation":"Las raíces en suelo seco producen ácido abscísico, que viaja por el xilema y cierra los estomas antes de que la hoja pierda turgencia."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m4-s4', 'm4-s4', 'Reguladores del Crecimiento', '[{"heading":"Las promotoras","body":["Las auxinas (ácido indolacético) se producen en ápices y semillas. Causan la dominancia apical, el enraizamiento de estacas y el crecimiento del fruto; sintéticas como el ANA se usan para enraizar y para ralear.","Las giberelinas alargan tallos, rompen la latencia de algunas semillas y agrandan bayas: en uva de mesa se aplica ácido giberélico (GA₃) para alargar el racimo y aumentar el calibre.","Las citoquininas, formadas en la raíz, estimulan la división celular, retrasan la senescencia y rompen la dominancia apical. El balance auxina/citoquinina decide si un tejido forma raíces o brotes."]},{"heading":"Etileno y ABA","body":["El etileno es un gas que desencadena la maduración de frutos climatéricos (manzana, palta, plátano, tomate) y la abscisión de hojas y frutos. En postcosecha se controla con frío, ventilación, atmósfera controlada y el 1-MCP, que bloquea sus receptores.","El ácido abscísico (ABA) induce la dormancia de yemas y semillas y cierra estomas ante sequía."]},{"heading":"Uso agronómico","body":["Los reguladores se usan a dosis muy bajas y el efecto depende de la especie, la variedad, la dosis y el estado fenológico. Un mismo producto puede ralear o cuajar según el momento.","Ejemplos: ethephon (libera etileno) para uniformar maduración o ralear, AVG para retrasar la caída de frutos y la maduración, prohexadiona-calcio para frenar el crecimiento de brotes."]}]'::jsonb, null, null, '[{"id":"m4-s4-cp1","timestamp_seconds":125,"prompt":"¿Qué aplicación aumenta el calibre de las bayas de uva de mesa?","options":["Ácido abscísico","Ácido giberélico (GA₃)","1-MCP","Ethephon en floración"],"correct_index":1,"explanation":"Las giberelinas estimulan la elongación celular: en uva de mesa el GA₃ agranda las bayas y elonga el raquis."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m4-s5', 'm4-s5', 'Fenología y Desarrollo', '[{"heading":"Fenología","body":["La fenología estudia las etapas del ciclo (brotación, floración, cuaja, pinta, cosecha, caída de hojas) y su relación con el clima. Las escalas BBCH codifican cada estado con dos dígitos para que todos hablen el mismo idioma.","Programar riego, fertilización y control de plagas según el estado fenológico, y no según el calendario, es la base del manejo moderno."]},{"heading":"Dormancia","body":["Paradormancia: la yema no brota porque otro órgano la inhibe (dominancia apical). Endodormancia: la inhibición está en la propia yema y solo la rompe la acumulación de frío. Ecodormancia: la yema ya está lista, pero espera temperaturas favorables.","Las semillas también tienen dormancia: por cubiertas duras (se rompe por escarificación) o por inhibidores internos (se rompe por estratificación en frío húmedo)."]},{"heading":"Inducción floral","body":["Algunas especies florecen según la duración del día (fotoperiodo): de día largo (espinaca, avena), de día corto (crisantemo, frutilla de día corto) o neutras.","La vernalización es el frío que necesitan algunos cultivos para florecer, como el trigo de invierno o la remolacha, que es bianual.","En frutales la inducción floral ocurre el verano anterior, en la temporada previa a la floración. Un exceso de carga frutal inhibe la inducción y genera añerismo: un año mucha fruta, el siguiente poca."]}]'::jsonb, null, null, '[{"id":"m4-s5-cp1","timestamp_seconds":155,"prompt":"Un manzano tuvo una cosecha muy cargada y al año siguiente casi no florece. ¿Qué fenómeno ocurrió?","options":["Vernalización insuficiente","Añerismo por inhibición de la inducción floral","Ecodormancia","Exceso de horas frío"],"correct_index":1,"explanation":"Las semillas de una carga alta inhiben la inducción floral del verano: el año siguiente hay pocas flores. El raleo temprano lo previene."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m5-s1', 'm5-s1', 'Morfología Vegetativa', '[{"heading":"Raíces","body":["Las dicotiledóneas suelen tener raíz pivotante: un eje principal que profundiza (alfalfa, zanahoria). Las monocotiledóneas tienen raíces fasciculadas, un haz de raíces finas de igual grosor (trigo, maíz, pastos).","Hay raíces adventicias, que nacen de tallos u hojas (estacas, raíces de anclaje del maíz), y raíces reservantes engrosadas (betarraga, camote)."]},{"heading":"Tallos y sus modificaciones","body":["El tallo tiene nudos, donde nacen hojas y yemas, y entrenudos. Muchas especies lo modifican: el rizoma es un tallo subterráneo horizontal (correhuela, chépica); el tubérculo es un tallo subterráneo engrosado con yemas u \"ojos\" (papa); el bulbo es un tallo corto rodeado de hojas carnosas (cebolla, ajo).","El estolón es un tallo rastrero que enraíza en los nudos (frutilla). Los zarcillos de la vid y las espinas de la zarzamora o del espino también son estructuras modificadas.","La papa es un tallo y no una raíz: sus \"ojos\" son yemas en nudos, y por eso brota de ellos."]},{"heading":"La hoja","body":["Partes: lámina, pecíolo y, en algunas, estípulas. Las monocotiledóneas suelen tener nervaduras paralelas y vaina que abraza el tallo; las dicotiledóneas, nervaduras reticuladas.","Una hoja es simple si tiene una sola lámina y compuesta si se divide en folíolos (el nogal, la rosa). La filotaxis describe cómo se ordenan en el tallo: alterna, opuesta o verticilada.","En las gramíneas, la lígula y las aurículas en la unión de la vaina con la lámina permiten identificar especies incluso sin flor."]}]'::jsonb, null, null, '[{"id":"m5-s1-cp1","timestamp_seconds":100,"prompt":"¿Por qué la papa se considera un tallo y no una raíz?","options":["Porque crece bajo tierra","Porque tiene yemas en nudos (\"ojos\")","Porque acumula almidón","Porque no tiene pelos radicales"],"correct_index":1,"explanation":"El tubérculo de papa es un tallo modificado: sus ojos son yemas ubicadas en nudos, desde donde brotan las nuevas plantas."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m5-s2', 'm5-s2', 'Morfología Reproductiva', '[{"heading":"La flor","body":["Una flor completa tiene cáliz (sépalos), corola (pétalos), androceo (estambres, con anteras que producen polen) y gineceo (pistilo: estigma, estilo y ovario).","El ovario es súpero si se ubica sobre la inserción de las otras piezas (cerezo, tomate) e ínfero si queda bajo ellas, fusionado al receptáculo (manzano, peral, zapallo).","Las flores pueden ser hermafroditas o unisexuales. Una especie es monoica si tiene flores masculinas y femeninas en la misma planta (maíz, nogal) y dioica si están en plantas distintas (kiwi, espárrago)."]},{"heading":"Del óvulo al fruto","body":["La polinización lleva el polen al estigma; la fecundación ocurre cuando el tubo polínico llega al óvulo. En las angiospermas es doble: un núcleo forma el embrión y otro el endosperma.","El fruto es el ovario desarrollado y la semilla, el óvulo fecundado. Si el fruto se desarrolla sin fecundación es partenocárpico (plátano, algunas mandarinas)."]},{"heading":"Tipos de fruto","body":["Carnosos: la drupa tiene un carozo leñoso (durazno, cereza, aceituna); la baya es carnosa con semillas en la pulpa (uva, tomate, arándano); el pomo es un falso fruto donde la parte comestible es el receptáculo (manzana, pera); el hesperidio es la baya de los cítricos.","Secos: la legumbre se abre por dos suturas (poroto, arveja); la cariopsis es el grano de los cereales, con la semilla soldada al pericarpio; la nuez es seca e indehiscente.","Frutos agregados vienen de varios pistilos de una flor (frambuesa, frutilla) y los múltiples, de varias flores (piña, mora de árbol)."]}]'::jsonb, null, null, '[{"id":"m5-s2-cp1","timestamp_seconds":140,"prompt":"¿Qué tipo de fruto es la manzana?","options":["Drupa","Baya","Pomo","Legumbre"],"correct_index":2,"explanation":"La manzana es un pomo: viene de un ovario ínfero y la parte comestible es el receptáculo floral engrosado."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m5-s3', 'm5-s3', 'Taxonomía Vegetal', '[{"heading":"El nombre científico","body":["Linneo propuso el sistema binomial: género con mayúscula y epíteto específico con minúscula, ambos en cursiva (Solanum tuberosum). A veces se agrega el autor abreviado (L. por Linneo).","Los nombres comunes cambian entre regiones (palta y aguacate, poroto y frijol); el científico es único y universal, por eso se usa en etiquetas de plaguicidas, registros y viveros."]},{"heading":"La jerarquía","body":["Reino, división, clase, orden, familia, género y especie. Los nombres de familia terminan en -aceae: Rosaceae, Fabaceae, Poaceae.","Bajo la especie están la subespecie, la variedad botánica y, en agricultura, el cultivar (variedad cultivada), que se escribe entre comillas simples: Malus domestica ''Gala''."]},{"heading":"Familias de importancia agrícola","body":["Rosaceae: manzano, peral, cerezo, frutilla, frambuesa. Fabaceae (leguminosas): poroto, arveja, alfalfa; fijan nitrógeno con Rhizobium. Poaceae (gramíneas): trigo, maíz, arroz, praderas.","Solanaceae: papa, tomate, ají, berenjena. Brassicaceae (crucíferas): repollo, brócoli, raps, rábano. Cucurbitaceae: zapallo, melón, sandía. Asteraceae: lechuga, maravilla, alcachofa.","Conocer la familia orienta la rotación: cultivos de la misma familia comparten plagas y enfermedades."]}]'::jsonb, null, null, '[{"id":"m5-s3-cp1","timestamp_seconds":115,"prompt":"¿Cuál es la forma correcta de escribir el nombre científico del tomate?","options":["solanum lycopersicum","Solanum Lycopersicum","Solanum lycopersicum (en cursiva)","SOLANUM LYCOPERSICUM"],"correct_index":2,"explanation":"Género con mayúscula, epíteto con minúscula, ambos en cursiva (o subrayados si se escribe a mano)."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m5-s4', 'm5-s4', 'Flora Nativa de Chile', '[{"heading":"Una isla biogeográfica","body":["Chile está aislado por el desierto, la cordillera y el océano. Por eso tiene una proporción alta de especies endémicas, que solo crecen aquí. La zona central es un \"hotspot\" mundial de biodiversidad.","Especies endémicas emblemáticas son la palma chilena (Jubaea chilensis), el belloto del norte, la araucaria (compartida con Argentina) y el ruil, uno de los árboles más amenazados del país."]},{"heading":"Bosque esclerófilo y matorral","body":["En la zona mediterránea domina el bosque esclerófilo: hojas duras, coriáceas y perennes que resisten la sequía estival. Sus especies típicas son el peumo, el boldo, el litre, el quillay y el maitén.","El espino (Vachellia caven) forma el espinal de los valles. Es una leguminosa que fija nitrógeno y crece en suelos degradados; se usa para leña y carbón, y como sombra para el ganado.","El quillay produce saponinas que se exportan para la industria alimentaria, de vacunas y de cosméticos; el boldo se usa como hierba medicinal."]},{"heading":"Bosque templado del sur","body":["Hacia el sur aparecen los bosques de Nothofagus (roble, raulí, coigüe, lenga), el bosque valdiviano lluvioso y los alerces (Fitzroya cupressoides), que pueden superar los 3.000 años.","Productos forestales no madereros como la murta (Ugni molinae), el maqui (Aristotelia chilensis, rico en antioxidantes), el calafate y la rosa mosqueta (introducida) tienen valor comercial creciente.","Proteger los remanentes de bosque nativo en los predios conserva polinizadores, controladores biológicos y fuentes de agua."]}]'::jsonb, null, null, '[{"id":"m5-s4-cp1","timestamp_seconds":150,"prompt":"¿Qué característica comparten las especies del bosque esclerófilo?","options":["Hojas grandes y caducas","Hojas duras y perennes que resisten la sequía","Raíces acuáticas","Floración en invierno con nieve"],"correct_index":1,"explanation":"Esclerófilo significa \"hoja dura\": hojas coriáceas y perennes adaptadas al verano seco mediterráneo."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m5-s5', 'm5-s5', 'Malezas: Biología e Identificación', '[{"heading":"Qué hace exitosa a una maleza","body":["Una maleza compite con el cultivo por luz, agua y nutrientes, y puede hospedar plagas. Las más agresivas producen miles de semillas, con dormancia que les permite esperar años en el banco de semillas del suelo.","Por su ciclo se clasifican en anuales (completan su vida en una temporada), bianuales y perennes. Las perennes con rizomas, estolones o bulbillos son las más difíciles, porque rebrotan aunque se corte la parte aérea."]},{"heading":"Hoja ancha y hoja angosta","body":["Las malezas de hoja angosta son principalmente gramíneas (pasto bermuda o chépica, hualcacho, ballica) y ciperáceas (chufa o coquito, Cyperus rotundus, con tubérculos). Las de hoja ancha son dicotiledóneas: yuyo, rábano silvestre, quingüilla, correhuela, malvilla.","La distinción importa porque muchos herbicidas son selectivos: los graminicidas controlan gramíneas sin dañar cultivos de hoja ancha, y las auxinas sintéticas (2,4-D, MCPA) controlan hojas anchas en cereales.","Las ciperáceas se distinguen de las gramíneas por su tallo triangular y macizo (\"las ciperáceas tienen aristas\")."]},{"heading":"Control integrado","body":["Identificar la maleza en estado de plántula permite controlarla cuando es más sensible. El momento crítico de competencia es el periodo en que el cultivo debe estar limpio para no perder rendimiento.","El manejo integrado combina rotación de cultivos, cultivos de cobertura, control mecánico, herbicidas de distintos modos de acción y evitar que las malezas semillen. Usar siempre el mismo herbicida selecciona biotipos resistentes, como la ballica resistente a glifosato.","La cuscuta es una planta parásita sin clorofila que se enrolla en el hospedero; la correhuela (Convolvulus arvensis) es una perenne de rizomas profundos que rebrota desde varios metros de profundidad."]}]'::jsonb, null, null, '[{"id":"m5-s5-cp1","timestamp_seconds":135,"prompt":"Una maleza tiene tallo triangular y macizo, hojas angostas y pequeños tubérculos en la raíz. ¿Qué es?","options":["Una gramínea como la chépica","Una ciperácea como la chufa","Una hoja ancha como el yuyo","Una cuscuta"],"correct_index":1,"explanation":"El tallo triangular y macizo es típico de las ciperáceas; la chufa (Cyperus rotundus) forma tubérculos que la hacen muy persistente."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m6-s1', 'm6-s1', 'Portainjertos e Injertos', '[{"heading":"Por qué injertar","body":["La variedad (copa) se propaga sobre un portainjerto para conservar sus características: de semilla saldría una planta distinta, porque la mayoría de los frutales son heterocigotos.","El portainjerto controla el vigor y el tamaño del árbol, la precocidad, la tolerancia a suelos (asfixia, caliza, salinidad) y la resistencia a plagas y enfermedades del suelo como nematodos y Phytophthora."]},{"heading":"Portainjertos clásicos","body":["Manzano: la serie Malling, como el M9 (enanizante, exige soporte y suelos buenos) y el MM106 o MM111 (más vigorosos). Cerezo: Gisela 6 y Gisela 12 (enanizantes y precoces), Colt, Maxma 14 o el franco Mazzard. Vid: portainjertos americanos resistentes a filoxera, como 1103 Paulsen o Freedom.","En Chile, gran parte de las vides se cultiva sobre pie franco porque el país está libre de filoxera; aun así se usan portainjertos contra nematodos, salinidad o falta de vigor."]},{"heading":"El injerto y su compatibilidad","body":["Para que prenda, el cambium de ambas partes debe quedar en contacto. Las técnicas más comunes son el injerto de yema (ojo vivo o dormido, chip budding) y los de púa (hendidura, inglés).","La incompatibilidad aparece cuando las especies están poco emparentadas: la unión es débil, con engrosamiento o necrosis, el árbol amarillea y puede quebrarse. Se evita con un interinjerto compatible, como en el peral sobre membrillero.","El injerto también transmite virus: por eso se usa material certificado."]}]'::jsonb, null, null, '[{"id":"m6-s1-cp1","timestamp_seconds":120,"prompt":"Se quiere un huerto de cerezos peatonal, de alta densidad y entrada rápida en producción. ¿Qué portainjerto conviene?","options":["Mazzard franco","Gisela 6","Pie franco de semilla","Membrillero"],"correct_index":1,"explanation":"Gisela 6 reduce el vigor y adelanta la producción, ideal para alta densidad. El Mazzard da árboles grandes y tardíos."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m6-s2', 'm6-s2', 'Conducción y Arquitectura del Huerto', '[{"heading":"La luz es la cosecha","body":["Un huerto produce según la luz que intercepta. Los sistemas de conducción buscan cubrir rápido el espacio, iluminar todo el árbol y facilitar la cosecha y la aplicación de productos.","La sombra interior baja la inducción floral, el color y el calibre de la fruta. Bajo un 30 % de luz plena las yemas pierden fertilidad."]},{"heading":"Sistemas","body":["Vaso abierto: tres a cinco ramas desde un tronco corto, con el centro despejado; tradicional en carozos. Eje central: un líder vertical con ramas laterales cortas que decrecen hacia arriba; base de los huertos de manzano en alta densidad.","Sistemas en pared o de ejes múltiples (KGB, UFO, Tall Spindle, ejes en V) forman muros frutales estrechos, fáciles de cosechar y aptos para la mecanización.","La vid se conduce en espaldera (vino) o parronal español (uva de mesa), donde el follaje forma un techo que protege los racimos."]},{"heading":"Densidad y vigor","body":["Las altas densidades (más de 2.000 árboles/ha en manzano) necesitan portainjertos enanizantes, soporte, riego tecnificado y mano de obra calificada, pero producen antes y con mejor calidad.","La orientación norte-sur de las hileras reparte mejor la luz entre ambas caras en Chile. La distancia entre hileras debe ser mayor que la altura del árbol para evitar el sombreamiento mutuo."]}]'::jsonb, null, null, '[{"id":"m6-s2-cp1","timestamp_seconds":130,"prompt":"Las hileras tienen 3,5 m de altura y están a 2,5 m entre sí. ¿Qué problema es esperable?","options":["Exceso de luz en la base","Sombreamiento de la parte baja y pérdida de calidad","Heladas por exceso de ventilación","Mejor color en toda la copa"],"correct_index":1,"explanation":"Si la altura supera la distancia entre hileras, los árboles se sombrean entre sí: la base pierde inducción, color y calibre."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m6-s3', 'm6-s3', 'Poda y Balance Vegetativo-Reproductivo', '[{"heading":"Principios de la poda","body":["La poda invernal estimula el vigor: al quitar yemas, la reserva de la raíz se reparte entre menos puntos de crecimiento. La poda de verano, en cambio, frena el vigor y mejora la luz sobre la fruta.","Despunte (rebaje) estimula brotes cerca del corte; raleo (eliminar una rama completa desde su base) abre la copa sin provocar rebrote excesivo."]},{"heading":"Dónde fructifica cada especie","body":["Antes de podar hay que saber dónde está la fruta: el manzano y el peral fructifican sobre dardos y lamburdas de madera de dos años o más; el durazno, en ramillas mixtas del año anterior; el cerezo, en dardos (ramilletes de mayo) y en la base de las ramillas de un año; la vid, en brotes nacidos de cargadores o pitones de madera de un año.","Una poda que elimina esa madera elimina la cosecha."]},{"heading":"Equilibrio y chupones","body":["Los chupones son brotes vigorosos y verticales que consumen carbohidratos, sombrean y rara vez fructifican. Aparecen tras podas fuertes, exceso de N o ramas arqueadas.","Un árbol equilibrado tiene crecimiento moderado de brotes y fruta suficiente. Exceso de vigor: poca fruta y mucha sombra. Poco vigor: fruta chica y envejecimiento de la madera.","Herramientas para frenar el vigor: poda de verano, inclinar ramas, anillado, portainjertos enanizantes, riego deficitario y reguladores como la prohexadiona-calcio."]}]'::jsonb, null, null, '[{"id":"m6-s3-cp1","timestamp_seconds":145,"prompt":"Un manzano joven tiene exceso de vigor y casi no florece. ¿Qué acción ayuda a equilibrarlo?","options":["Poda invernal fuerte de rebaje","Inclinar ramas y hacer poda de verano","Aplicar más nitrógeno","Regar más en primavera"],"correct_index":1,"explanation":"La poda invernal fuerte estimularía más vigor. Inclinar ramas y podar en verano frena el crecimiento y favorece la inducción floral."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m6-s4', 'm6-s4', 'Polinización, Cuaja y Raleo', '[{"heading":"Autoincompatibilidad y polinizantes","body":["Muchas variedades de manzano, peral y cerezo son autoincompatibles: su polen no fecunda sus propias flores. Necesitan una variedad polinizante compatible, que florezca al mismo tiempo, intercalada en el huerto.","En cerezo la compatibilidad depende de los alelos S: variedades con el mismo grupo S no se polinizan entre sí. Existen variedades autofértiles, como Lapins o Santina, que simplifican el diseño."]},{"heading":"Abejas y cuaja","body":["Las abejas melíferas son el principal polinizador; se recomiendan del orden de 6 a 10 colmenas fuertes por hectárea en cerezo o manzano, ubicadas al inicio de la floración. Los abejorros (Bombus) trabajan con menos temperatura.","La cuaja es el paso de flor a fruto en crecimiento. El clima frío y lluvioso en floración, las heladas y la falta de reservas reducen la cuaja; el periodo efectivo de polinización depende de la vida útil del óvulo."]},{"heading":"Raleo","body":["Un árbol con demasiada fruta produce fruta chica, de menor azúcar y color, y puede no florecer el año siguiente (añerismo). El raleo ajusta la carga a la capacidad del árbol.","Puede ser de flores o de frutos, manual o químico (ANA, BA o metamitrón en manzano). Mientras más temprano, mayor es el efecto sobre el calibre final, porque la división celular del fruto ocurre en las primeras semanas."]}]'::jsonb, null, null, '[{"id":"m6-s4-cp1","timestamp_seconds":160,"prompt":"Un huerto nuevo de cerezos se plantó solo con una variedad autoincompatible. ¿Qué se espera?","options":["Cuaja normal gracias al viento","Muy baja cuaja por falta de polinizante compatible","Frutos más grandes","Floración más temprana"],"correct_index":1,"explanation":"Sin una variedad compatible que florezca a la vez, el polen disponible no fecunda los óvulos y la cuaja es muy baja."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m6-s5', 'm6-s5', 'Madurez y Postcosecha', '[{"heading":"Índices de cosecha","body":["Se cosecha según índices objetivos: sólidos solubles (°Brix, con refractómetro), firmeza (presionómetro, en lb o kg), color de fondo y de cubrimiento, acidez titulable, test de almidón con yodo en manzana y materia seca en palta.","El momento de cosecha define el potencial de guarda: una manzana cosechada muy madura no aguanta meses en frío; una muy inmadura nunca desarrolla sabor."]},{"heading":"Climatéricos y no climatéricos","body":["Los frutos climatéricos (manzana, pera, kiwi, palta, durazno, tomate) tienen un alza de respiración y etileno al madurar: pueden cosecharse fisiológicamente maduros y terminar de madurar después. La palta incluso solo madura fuera del árbol.","Los no climatéricos (cereza, uva, cítricos, frutilla, frambuesa) no siguen madurando tras la cosecha: hay que cosecharlos en su punto."]},{"heading":"Cadena de frío","body":["Cada hora a temperatura de campo acorta la vida de la fruta. El pre-enfriado rápido (hidrocooling, aire forzado) baja la temperatura en horas; luego la fruta debe mantenerse en frío sin quiebres hasta el consumidor.","La atmósfera controlada (bajo O₂ y alto CO₂) reduce la respiración y prolonga la guarda de manzanas por meses. El 1-MCP bloquea la acción del etileno.","Algunas especies sufren daño por frío bajo cierta temperatura (palta, tomate, plátano, cítricos), con manchas y pardeamiento: no todas se guardan a 0 °C."]}]'::jsonb, null, null, '[{"id":"m6-s5-cp1","timestamp_seconds":150,"prompt":"¿Cuál de estas frutas no sigue madurando después de cosechada?","options":["Palta","Kiwi","Cereza","Pera"],"correct_index":2,"explanation":"La cereza es no climatérica: no aumenta su azúcar ni su color tras la cosecha, por eso se cosecha en su punto óptimo."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m7-s1', 'm7-s1', 'Biología del Cranberry y su Suelo', '[{"heading":"Una planta de turbera","body":["El cranberry (Vaccinium macrocarpon) es una Ericácea perenne y siempreverde, nativa de las turberas de Norteamérica. Se cultiva en \"camas\" planas y niveladas, sobre arena o suelos orgánicos, que pueden inundarse y drenarse.","Forma tallos rastreros (runners), que cubren la cama, y tallos verticales (uprights), que son los productivos: fructifican en la yema apical formada la temporada anterior. Una cama productiva tiene del orden de 400 a 600 uprights por pie cuadrado."]},{"heading":"Raíces superficiales","body":["Sus raíces son finas, sin pelos radicales, y se concentran en los primeros 10 a 15 cm. Dependen de micorrizas ericoides para absorber nutrientes.","Esa raíz tan superficial la hace sensible a la sequía, a la salinidad y a la asfixia: el mal drenaje favorece a Phytophthora cinnamomi."]},{"heading":"pH y nitrógeno","body":["Es una especie acidófila: su pH óptimo está entre 4,0 y 5,5. Sobre pH 6,5 bloquea la absorción de hierro y aparece clorosis intervenal en los brotes nuevos.","Absorbe mal el nitrato: exige nitrógeno amoniacal (sulfato de amonio, por ejemplo), que además ayuda a mantener el suelo ácido. Las dosis de N son bajas, porque el exceso vuelve la planta vegetativa."]}]'::jsonb, null, null, '[{"id":"m7-s1-cp1","timestamp_seconds":100,"prompt":"Una cama de cranberry tiene pH 6,8 y los brotes nuevos se ven amarillos con nervaduras verdes. ¿Qué ocurre?","options":["Exceso de nitrógeno amoniacal","Bloqueo de hierro por pH alto","Falta de horas frío","Daño por Cottonball"],"correct_index":1,"explanation":"Sobre pH 6,5 el hierro deja de estar disponible para esta acidófila: clorosis intervenal en hojas nuevas. Se corrige acidificando (azufre) y con fuentes amoniacales."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m7-s2', 'm7-s2', 'Riego y Manejo Térmico', '[{"heading":"Riego","body":["Con raíces en los primeros 15 cm, el cranberry tolera poco el déficit hídrico pero tampoco el exceso. En camas de arena se riega con tensiómetros, manteniendo la tensión entre 20 y 30 centibares.","El riego por aspersión cumple tres funciones: hidratar, proteger contra heladas y enfriar la fruta en días de calor."]},{"heading":"Heladas","body":["En invierno profundo, ya endurecida, la planta tolera hasta cerca de −18 °C. En primavera, con brotes y flores, la tolerancia cae a pocos grados bajo cero.","El control activo es la aspersión continua: al congelarse, el agua libera calor latente y mantiene los tejidos cerca de 0 °C. Debe seguir hasta que el hielo se derrita. Si el hielo se ve opaco y seco en vez de transparente y goteando, la tasa de agua es insuficiente y la planta se está congelando."]},{"heading":"Calor y color","body":["Con alta radiación y temperatura aparece el golpe de sol (sunscald): daño fisiológico en la cara expuesta de la baya. Riegos cortos de enfriamiento lo reducen.","El color rojo depende de las antocianinas, cuya síntesis se gatilla con noches frías al final de la temporada."]}]'::jsonb, null, null, '[{"id":"m7-s2-cp1","timestamp_seconds":140,"prompt":"Durante una noche de helada con aspersión, el hielo sobre las plantas se ve blanco, opaco y seco. ¿Qué indica?","options":["Protección perfecta","La tasa de agua es insuficiente y el tejido se enfría","Exceso de agua que hay que cortar","Que ya terminó la helada"],"correct_index":1,"explanation":"Con suficiente agua el hielo es transparente y gotea (sigue liberando calor). El hielo opaco y seco indica que falta agua: hay que aumentar la tasa."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m7-s3', 'm7-s3', 'Manejo de Camas de Cranberry', '[{"heading":"Establecimiento y variedades","body":["Las camas se plantan con estacas de runners presionadas en la arena; tardan 3 a 5 años en cubrir y entrar en plena producción, y pueden producir por décadas.","Stevens es la variedad histórica más productiva; hoy existen variedades de alto rendimiento y color como las de la serie de Rutgers."]},{"heading":"Arenado (sanding)","body":["Cada pocos años se aplica una capa delgada de arena (1 a 2,5 cm) sobre la cama, normalmente en invierno. Entierra parcialmente los runners, estimula su enraizamiento y la formación de nuevos uprights, y rejuvenece la cama.","También ayuda a controlar algunos insectos y a mejorar el drenaje superficial."]},{"heading":"Poda, peinado y vigor","body":["La poda de runners mantiene la cama densa en uprights; una poda severa baja temporalmente el rendimiento, pero aumenta el calibre. En primavera se usan peinadoras para alinear los runners y facilitar la cosecha.","El exceso de nitrógeno produce \"emboscamiento\": demasiados runners y follaje, menos flores, fruta blanda y más enfermedades. El N se dosifica según el vigor observado."]}]'::jsonb, null, null, '[{"id":"m7-s3-cp1","timestamp_seconds":125,"prompt":"Una cama vieja tiene pocos uprights y runners largos sin enraizar. ¿Qué práctica la rejuvenece?","options":["Más nitrógeno nítrico","Arenado (sanding)","Inundación de verano","Retirar las abejas"],"correct_index":1,"explanation":"La capa de arena entierra los runners, estimula raíces nuevas y la formación de uprights productivos."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m7-s4', 'm7-s4', 'Sanidad del Cranberry', '[{"heading":"Enfermedades","body":["Phytophthora cinnamomi pudre las raíces en sectores mal drenados: aparecen manchones de plantas rojizas y débiles. La prevención es el drenaje y la nivelación de las camas.","El Fairy Ring, asociado al hongo Psilocybe, forma anillos que se expanden cada año, con plantas muertas en el borde activo."]},{"heading":"Insectos","body":["El cranberry fruitworm pone huevos en las bayas recién cuajadas y la larva consume su interior: se monitorea post-cuaja. La mosquita de la yema (Dasineura oxycoccana) mata las yemas apicales de uprights tiernos y reduce la floración siguiente.","El manejo integrado combina monitoreo con trampas y redes, umbrales de daño y productos compatibles con las abejas, indispensables para la polinización."]},{"heading":"Malezas","body":["La cuscuta es una planta parásita sin clorofila: sus tallos amarillo-anaranjados se enrollan en el cranberry y le extraen savia mediante haustorios. Se dispersa por semillas y fragmentos, y es la maleza más problemática.","Pastos, juncos y helechos compiten en camas mal establecidas; mantener la cama densa es la mejor defensa."]}]'::jsonb, null, null, '[{"id":"m7-s4-cp1","timestamp_seconds":135,"prompt":"En la cama aparecen tallos amarillo-anaranjados sin hojas, enrollados sobre las plantas. ¿Qué es?","options":["Fairy Ring","Cuscuta","Daño por fruitworm","Clorosis férrica"],"correct_index":1,"explanation":"La cuscuta es una enredadera parásita sin clorofila que se enrolla y succiona al hospedero con haustorios."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m7-s5', 'm7-s5', 'Polinización, Cosecha y Calidad de Fruta', '[{"heading":"Polinización","body":["La flor del cranberry produce poco néctar y su polen se libera en tétradas desde anteras tubulares, por lo que la polinización necesita insectos. Se introducen colmenas de abejas melíferas o colonias de abejorros durante la floración.","Una buena polinización aumenta el número de semillas por baya, y con ellas el tamaño del fruto."]},{"heading":"Cosecha en agua y en seco","body":["Para la industria (jugos, fruta deshidratada) se cosecha en agua: se inunda la cama, batidoras desprenden las bayas y estas flotan gracias a sus cámaras de aire internas; luego se arrean con barreras flotantes.","Para mercado fresco se cosecha en seco, con peinadoras mecánicas. La fruta cosechada en agua dura poco, porque los patógenos entran por la cicatriz del pedicelo y por el daño de la batidora."]},{"heading":"Calidad","body":["El precio de la fruta para industria depende mucho del color, que se mide como antocianinas totales (TAcy). Cosechar después de algunas noches frías mejora el valor.","El hongo Cottonball (Monilinia oxycocci) infecta flores y la baya se llena de una masa algodonosa blanca. Las pudriciones de campo se manejan con fungicidas en floración y buena ventilación de la cama."]}]'::jsonb, null, null, '[{"id":"m7-s5-cp1","timestamp_seconds":150,"prompt":"¿Por qué flotan las bayas de cranberry en la cosecha en agua?","options":["Porque tienen aceite","Porque tienen cámaras de aire internas","Porque se cosechan verdes","Porque se les agrega sal al agua"],"correct_index":1,"explanation":"La baya tiene cuatro cámaras de aire en su interior: flota y puede arrearse en la superficie de la cama inundada."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m8-s1', 'm8-s1', 'Biología de la Frambuesa', '[{"heading":"Raíz perenne, cañas bianuales","body":["La frambuesa (Rubus idaeus) es una Rosácea con raíz y corona perennes, pero sus cañas viven dos temporadas. El primer año la caña se llama primocane (crece vegetativa); el segundo, floricane (fructifica y luego muere).","Brota desde yemas de la corona y desde raíces gemíferas que emiten hijuelos a distancia: por eso la plantación \"camina\" y puede volverse invasiva entre hileras."]},{"heading":"Remontantes y no remontantes","body":["Las variedades no remontantes (floricane, como Meeker) fructifican en verano sobre la caña de segundo año, después de acumular entre 600 y 1.000 horas frío en receso.","Las remontantes (primocane, como Heritage, la más plantada en Chile) fructifican en otoño en la punta de la caña del mismo año, por lo que pueden manejarse con una sola cosecha anual cortando todas las cañas en invierno, o con doble cosecha."]},{"heading":"Flor y fruto","body":["La flor es muy atractiva para las abejas, que aumentan la cuaja: cada drupéolo es un pistilo fecundado, de modo que una mala polinización deja frutos deformes.","El fruto es un agregado de drupéolos. A diferencia de la mora, al cosecharlo el receptáculo queda en la planta y la frambuesa sale hueca."]}]'::jsonb, null, null, '[{"id":"m8-s1-cp1","timestamp_seconds":110,"prompt":"Una plantación de Heritage se poda cortando todas las cañas a ras en invierno. ¿Cuándo cosechará?","options":["En primavera temprana","En verano, sobre floricanes","En otoño, sobre las cañas nuevas del año","No cosechará hasta el segundo año"],"correct_index":2,"explanation":"Heritage es remontante: fructifica en la punta de las primocanes del mismo año, en otoño."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m8-s2', 'm8-s2', 'Establecimiento, Riego y Nutrición', '[{"heading":"Suelo y camellones","body":["La raíz de la frambuesa es muy sensible a la falta de oxígeno y a Phytophthora. Se planta en camellones elevados de 30 a 40 cm, en suelos profundos, francos y bien drenados.","Antes de plantar conviene analizar nematodos: Pratylenchus, un endoparásito migratorio, destruye el tejido de la raíz al desplazarse por ella."]},{"heading":"Riego","body":["El sistema más usado es el goteo con doble cinta sobre el camellón: moja la franja de raíces sin saturar y permite fertirrigar.","La demanda es máxima en cosecha: el déficit en esa etapa reduce el calibre y aumenta el ablandamiento de la fruta."]},{"heading":"Nutrición","body":["El potasio se asocia a la firmeza y la calidad de la fruta. Como la frambuesa es sensible al cloro, se prefiere sulfato o nitrato de potasio en vez de cloruro (muriato).","El calcio aplicado al follaje después de la cuaja llega poco al fruto, porque viaja por el xilema hacia los órganos que más transpiran, las hojas."]}]'::jsonb, null, null, '[{"id":"m8-s2-cp1","timestamp_seconds":120,"prompt":"¿Por qué se recomienda plantar frambuesa en camellones elevados?","options":["Para cosechar a máquina","Porque su raíz es muy sensible a la asfixia y a Phytophthora","Para evitar heladas de primavera","Para usar menos plantas"],"correct_index":1,"explanation":"El camellón aleja la raíz del agua acumulada: menos asfixia y menos Phytophthora."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m8-s3', 'm8-s3', 'Conducción y Manejo de Cañas', '[{"heading":"Conducción en V","body":["Las cañas se conducen con alambres. El sistema en \"V\" o cruceta (T-trellis) separa las cañas hacia ambos lados: abre el centro de la hilera, mejora la luz y la aireación y reduce Botrytis.","Una hilera densa y cerrada guarda humedad, favorece enfermedades y complica la cosecha."]},{"heading":"Raleo y eliminación de cañas","body":["En variedades no remontantes, las primocanes compiten con las floricanes que están produciendo: se ralean temprano, dejando las más vigorosas. Un raleo tardío deja cañas débiles para el año siguiente.","Tras la cosecha, las floricanes se cortan a ras y se sacan del huerto: ya no producirán y pueden hospedar enfermedades."]},{"heading":"Exposición de la fruta","body":["Con radiación UV directa y altas temperaturas aparece el White Drupelet Disorder: drupéolos blancos que bajan la calidad. Una canopia que proteja la fruta y mallas sombra en zonas cálidas lo reducen."]}]'::jsonb, null, null, '[{"id":"m8-s3-cp1","timestamp_seconds":130,"prompt":"En una variedad floricane, las primocanes crecieron muy densas y nadie las raleó. ¿Qué se espera?","options":["Más fruta este verano","Competencia con la floricane, más Botrytis y cañas débiles para el próximo año","Ningún efecto","Cosecha anticipada"],"correct_index":1,"explanation":"El exceso de primocanes sombrea y compite con la caña productiva, aumenta la humedad (Botrytis) y deja cañas débiles para la próxima temporada."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m8-s4', 'm8-s4', 'Sanidad de la Frambuesa', '[{"heading":"Enfermedades","body":["Botrytis cinerea causa pudrición gris en flores y frutos, sobre todo con lluvia en floración y cosecha. El Spur blight (tizón de la yema, Didymella applanata) deja manchas púrpura oscuras en los nudos de la caña.","Agrobacterium tumefaciens forma agallas leñosas en el cuello y las raíces; entra por heridas y se evita con plantas sanas y certificadas.","Virus como el RBDV causan desgrane (crumbly berry); otros, como los mosaicos, los transmiten pulgones."]},{"heading":"Plagas","body":["El burrito de la frambuesa (Aegorhinus superciliosus) es un curculiónido nativo: el adulto come brotes, pero el daño letal lo hace la larva, que barrena la corona y las raíces principales.","La arañita roja prolifera con calor y polvo, como en hileras junto a caminos de tierra: humedecer los caminos y conservar sus enemigos naturales ayuda a controlarla."]}]'::jsonb, null, null, '[{"id":"m8-s4-cp1","timestamp_seconds":140,"prompt":"Plantas de frambuesa se secan de golpe y al arrancarlas aparecen larvas blancas sin patas en la corona. ¿Qué plaga es?","options":["Drosophila suzukii","Burrito (Aegorhinus)","Arañita roja","Pulgón"],"correct_index":1,"explanation":"Las larvas del burrito barrenan la corona y las raíces principales, provocando la muerte de la planta."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m8-s5', 'm8-s5', 'Cosecha y Postcosecha', '[{"heading":"Cosecha","body":["La frambuesa se cosecha cada 2 o 3 días durante la temporada. Para mercado fresco se cosecha temprano en la mañana, sin calor de campo, directamente al envase final para no manipularla de nuevo.","Gran parte de la frambuesa chilena se congela (IQF) para exportación, lo que permite cosechar fruta más madura que para el mercado fresco."]},{"heading":"Pre-frío y atmósfera","body":["Su tasa respiratoria es altísima: cada hora a temperatura ambiente acorta su vida. Debe entrar a un túnel de pre-frío (aire forzado a 0 °C) dentro de 2 a 4 horas desde la cosecha.","Durante el transporte se usa atmósfera modificada con CO₂ elevado, que frena la respiración y a Botrytis."]},{"heading":"Drosophila suzukii","body":["A diferencia de otras drosófilas, la hembra de D. suzukii tiene un ovipositor aserrado que corta la piel de la fruta sana en maduración. Sus larvas blancas se desarrollan dentro del fruto.","Se maneja con monitoreo con trampas, cosechas frecuentes, eliminación de fruta caída o sobremadura y enfriamiento rápido."]}]'::jsonb, null, null, '[{"id":"m8-s5-cp1","timestamp_seconds":160,"prompt":"La fruta se cosechó a las 11:00 y llegó al túnel de pre-frío a las 18:00. ¿Qué problema hay?","options":["Ninguno: lo importante es llegar el mismo día","Se superó la ventana de 2-4 horas: menor vida postcosecha","La fruta debió congelarse en el campo","Debió lavarse antes del pre-frío"],"correct_index":1,"explanation":"Por su respiración altísima, la frambuesa debe enfriarse antes de 2 a 4 horas. Siete horas con calor de campo acortan mucho su vida."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m9-s1', 'm9-s1', 'Fisiología de Hortalizas', '[{"heading":"Estación fría y estación cálida","body":["Las hortalizas de estación fría (lechuga, repollo, brócoli, arveja, espinaca, ajo) crecen mejor entre 15 y 20 °C y toleran heladas suaves. Las de estación cálida (tomate, pimiento, poroto, zapallo, melón, sandía) necesitan más de 18-20 °C y no toleran heladas.","Sembrar cada especie en su ventana térmica evita problemas como la emisión prematura del tallo floral o la mala cuaja."]},{"heading":"Fotoperiodo y vernalización","body":["La cebolla forma bulbo cuando el día supera un largo crítico: hay cultivares de día corto (para siembras de otoño en el norte) y de día largo (para el sur o siembras de primavera). Un cultivar mal elegido no bulba o bulba antes de tiempo, con bulbos pequeños.","La lechuga y la espinaca se \"suben\" (emiten el tallo floral) con días largos y calor, y pierden calidad. Las brassicas bianuales, como el repollo, pueden florecer prematuramente si un frío prolongado las vernaliza cuando ya son plantas grandes."]},{"heading":"Órganos cosechados","body":["Se cosechan hojas (lechuga, acelga), inflorescencias (brócoli, coliflor, alcachofa), raíces (zanahoria, betarraga), tubérculos (papa), bulbos (cebolla, ajo), frutos inmaduros (pepino, zapallo italiano, poroto verde) o maduros (tomate, melón).","El órgano cosechado define el manejo: las hortalizas de hoja necesitan más nitrógeno y agua constante; las de fruto, más potasio y una buena cuaja."]}]'::jsonb, null, null, '[{"id":"m9-s1-cp1","timestamp_seconds":115,"prompt":"En el sur de Chile se sembró en primavera una cebolla de día corto. ¿Qué es esperable?","options":["Bulbos grandes en otoño","Bulbificación prematura con bulbos pequeños","Que nunca germine","Que florezca en invierno"],"correct_index":1,"explanation":"Los días largos del verano austral superan con creces el umbral de un cultivar de día corto: bulba muy temprano y queda pequeño."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m9-s2', 'm9-s2', 'Almácigos y Trasplante', '[{"heading":"Siembra directa o almácigo","body":["Algunas hortalizas se siembran directo porque su raíz no tolera el trasplante (zanahoria, rábano, arveja, poroto). Otras se producen en almácigo y se trasplantan (tomate, pimiento, lechuga, cebolla, brassicas), lo que ahorra semilla cara y acorta el tiempo en campo.","Las bandejas alveoladas (speedling) producen plantas con un pan de raíces que se trasplanta casi sin estrés."]},{"heading":"Sustrato y ambiente","body":["Un buen sustrato es liviano, poroso, retiene agua y está libre de patógenos y malezas: turba, fibra de coco, perlita o vermiculita. La temperatura óptima de germinación varía: el tomate germina mejor cerca de 25 °C; la lechuga se inhibe sobre unos 28 °C (termodormancia).","Antes del trasplante se \"endurecen\" las plantas: menos riego y más exposición al exterior, para que toleren el cambio."]},{"heading":"Caída de plántulas","body":["El damping-off (caída de almácigos) lo causan hongos y oomicetos del suelo como Pythium, Rhizoctonia y Fusarium: las plántulas se estrangulan en el cuello y caen.","Lo favorecen el exceso de riego, la mala ventilación, sembrar muy denso y usar sustratos o bandejas contaminadas. Se previene con sustrato nuevo, bandejas desinfectadas, riego moderado y buena aireación."]}]'::jsonb, null, null, '[{"id":"m9-s2-cp1","timestamp_seconds":130,"prompt":"Un almácigo regado en exceso y muy denso muestra plántulas que se doblan en el cuello y caen. ¿Qué es?","options":["Termodormancia","Damping-off (Pythium, Rhizoctonia)","Falta de nitrógeno","Exceso de luz"],"correct_index":1,"explanation":"El estrangulamiento del cuello en plántulas es el damping-off, favorecido por exceso de agua y poca ventilación."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m9-s3', 'm9-s3', 'Control del Clima en Invernadero', '[{"heading":"El efecto invernadero","body":["La cubierta deja pasar la radiación solar y retiene parte del calor: de día sube la temperatura y de noche se pierde menos. Los plásticos térmicos (con aditivos que bloquean el infrarrojo largo) reducen el enfriamiento nocturno.","En verano el problema es el exceso de calor: se maneja con ventilación cenital y lateral, mallas sombra, blanqueo de la cubierta y nebulización."]},{"heading":"Humedad y DPV","body":["El déficit de presión de vapor (DPV) resume humedad y temperatura. Un DPV muy bajo (aire saturado) frena la transpiración, reduce la absorción de calcio y favorece Botrytis y mildiú; un DPV muy alto estresa y cierra estomas.","Para la mayoría de los cultivos se busca un DPV aproximado de 0,5 a 1,2 kPa. Si la cubierta o las plantas se enfrían bajo el punto de rocío, el agua se condensa y gotea sobre el cultivo."]},{"heading":"Ventilación y CO₂","body":["Ventilar renueva el aire, saca humedad y calor y repone el CO₂ que las plantas consumen. En un invernadero cerrado y soleado el CO₂ puede caer muy bajo y limitar la fotosíntesis; algunos productores lo enriquecen hasta 700-1.000 ppm.","Las ventanas cenitales son más eficientes que las laterales porque el aire caliente sube (efecto chimenea)."]}]'::jsonb, null, null, '[{"id":"m9-s3-cp1","timestamp_seconds":145,"prompt":"Al amanecer el invernadero tiene 98 % de humedad y gotea agua desde la cubierta. ¿Qué riesgo aumenta y qué conviene hacer?","options":["Arañita roja: cerrar todo","Botrytis y mildiú: ventilar y calentar suavemente para bajar la humedad","Golpe de sol: blanquear la cubierta","Deficiencia de N: fertilizar"],"correct_index":1,"explanation":"Con DPV casi nulo y agua libre sobre las hojas, los hongos germinan fácilmente. Ventilar y subir algo la temperatura reduce la humedad."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m9-s4', 'm9-s4', 'Fertirriego e Hidroponía', '[{"heading":"Fertirriego","body":["El fertirriego entrega agua y nutrientes juntos por goteo, en pequeñas dosis frecuentes. Se controla midiendo la conductividad eléctrica (CE) y el pH de la solución en el gotero y en el drenaje.","Para tomate en producción se trabaja con CE cercanas a 2-3 dS/m y pH entre 5,5 y 6,5. No se deben mezclar en el mismo estanque calcio con sulfatos o fosfatos, porque precipitan y tapan goteros: se usan estanques A y B separados."]},{"heading":"Cultivo sin suelo","body":["En sustratos (fibra de coco, lana de roca, perlita) o en hidroponía pura (NFT, raíz flotante) toda la nutrición depende de la solución. Las ventajas: evita patógenos del suelo, controla mejor la nutrición y logra rendimientos altos.","Se riega con un porcentaje de drenaje (20 a 30 %) para evitar la acumulación de sales en la zona de raíces; si la CE del drenaje sube mucho sobre la del gotero, hay que aumentar el drenaje."]},{"heading":"Desórdenes nutricionales típicos","body":["La pudrición apical del tomate y el pimiento es una deficiencia de calcio en el fruto, ligada a riego irregular, alta CE o baja transpiración, más que a falta de calcio en la solución.","El tip burn de la lechuga también es falta de calcio en hojas jóvenes que transpiran poco, en cabezas que crecen muy rápido."]}]'::jsonb, null, null, '[{"id":"m9-s4-cp1","timestamp_seconds":150,"prompt":"El gotero entrega CE 2,5 dS/m y el drenaje mide 5,0 dS/m. ¿Qué indica?","options":["Que falta fertilizante","Acumulación de sales: hay que aumentar el porcentaje de drenaje","Que el pH es perfecto","Que la planta absorbe demasiada agua"],"correct_index":1,"explanation":"Si el drenaje duplica la CE del gotero, las sales se están acumulando en el sustrato: se debe lavar con más drenaje."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m9-s5', 'm9-s5', 'Manejo Integrado de Plagas en Hortalizas', '[{"heading":"Plagas clave","body":["La mosquita blanca (Trialeurodes vaporariorum y Bemisia tabaci) succiona savia desde el envés, produce mielecilla donde crece fumagina y transmite virus. Los trips (Frankliniella occidentalis) dañan flores y frutos y transmiten el virus del bronceado del tomate (TSWV).","La polilla del tomate (Tuta absoluta) mina hojas, tallos y frutos: es la plaga más importante del tomate en Chile."]},{"heading":"Monitoreo y barreras","body":["El monitoreo con trampas adhesivas amarillas (mosquita blanca) y azules (trips), y con feromonas para Tuta absoluta, permite actuar antes de llegar al umbral de daño.","Las mallas antiinsectos en ventanas, la doble puerta, la eliminación de malezas hospederas y de restos de cultivo cortan la entrada y el ciclo de las plagas."]},{"heading":"Control biológico","body":["En invernadero el control biológico funciona muy bien porque el ambiente es cerrado: Encarsia formosa parasita ninfas de mosquita blanca; ácaros depredadores como Amblyseius swirskii atacan mosquita blanca y trips; Phytoseiulus persimilis controla arañita roja.","El uso de insecticidas de amplio espectro mata a esos enemigos naturales; por eso el manejo integrado prioriza productos selectivos y rota modos de acción para evitar resistencia."]}]'::jsonb, null, null, '[{"id":"m9-s5-cp1","timestamp_seconds":160,"prompt":"Se liberó Encarsia formosa contra mosquita blanca y ahora aparece arañita roja. ¿Qué conviene?","options":["Aplicar un insecticida de amplio espectro","Liberar Phytoseiulus persimilis y no usar productos que dañen a Encarsia","Cerrar el invernadero sin ventilar","Aumentar el nitrógeno"],"correct_index":1,"explanation":"Un amplio espectro eliminaría a Encarsia. Phytoseiulus persimilis es el depredador específico de la arañita roja."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m10-s1', 'm10-s1', 'Cómo Identificar un Ave', '[{"heading":"Topografía del ave","body":["Para describir un ave se usan zonas: corona, ceja (supercilio), lorum, garganta, pecho, vientre, dorso, rabadilla, cubiertas alares, plumas primarias y secundarias (remiges) y plumas de la cola (rectrices).","Marcas como una ceja blanca, una banda alar o el color de la rabadilla suelen bastar para separar especies parecidas."]},{"heading":"El pico revela la dieta","body":["Pico cónico y grueso: granívoro (chincol, diuca, gorrión). Pico fino y recto: insectívoro (cachudito, golondrina). Pico ganchudo: rapaz o carroñero (tiuque, cernícalo). Pico largo y fino: nectarívoro (picaflor). Pico ancho y aplanado: filtrador (patos).","La forma de las patas también informa: garras fuertes en rapaces, patas palmeadas en aves acuáticas, dedos largos en aves que caminan sobre vegetación flotante."]},{"heading":"Más allá de la forma","body":["El dimorfismo sexual puede confundir: el macho de loica tiene el pecho rojo intenso y la hembra es más pálida. Los juveniles a menudo tienen plumajes distintos a los adultos.","El canto, el comportamiento (cómo vuela, si camina o salta), el hábitat y la época del año completan la identificación. Unos binoculares 8x42, una guía de campo y plataformas como eBird ayudan a registrar observaciones con valor científico."]}]'::jsonb, null, null, '[{"id":"m10-s1-cp1","timestamp_seconds":105,"prompt":"Un ave pequeña tiene pico corto, cónico y grueso, y se alimenta en el suelo de un rastrojo. ¿Qué dieta es más probable?","options":["Nectarívora","Granívora","Rapaz","Filtradora"],"correct_index":1,"explanation":"El pico cónico y grueso sirve para partir semillas: es típico de granívoros como el chincol o la diuca."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m10-s2', 'm10-s2', 'Aves Rapaces en el Agroecosistema', '[{"heading":"Rapaces diurnas","body":["El tiuque (Milvago chimango) es un falcónido oportunista: come insectos, larvas que deja el arado, roedores y carroña, y es muy común en potreros. El cernícalo (Falco sparverius) es un halcón pequeño que caza insectos y roedores desde perchas o suspendido en el aire.","El peuco (Parabuteo unicinctus), el aguilucho (Geranoaetus polyosoma) y el águila (Geranoaetus melanoleucus) completan el gremio de rapaces diurnas de los campos chilenos."]},{"heading":"Rapaces nocturnas","body":["La lechuza (Tyto alba) caza casi exclusivamente roedores: una pareja con polluelos puede consumir miles al año. Entre sus presas está el ratón colilargo, reservorio del virus Hanta.","El tucúquere (Bubo magellanicus) es el búho más grande de Chile; el chuncho (Glaucidium nana) es pequeño y también caza de día.","Las egagrópilas, bolos de pelos y huesos que las rapaces regurgitan, permiten estudiar su dieta sin capturarlas."]},{"heading":"Atraerlas al predio","body":["Las cajas nido para lechuzas y las perchas para rapaces diurnas en huertos y viñas aumentan la presión de depredación sobre roedores.","Los rodenticidas anticoagulantes son un riesgo para ellas: una rapaz que come roedores envenenados se intoxica (envenenamiento secundario). El control biológico y los cebos protegidos son la alternativa.","Todas las rapaces están protegidas por la Ley de Caza: está prohibido cazarlas o capturarlas."]}]'::jsonb, null, null, '[{"id":"m10-s2-cp1","timestamp_seconds":130,"prompt":"Un huerto con problemas de roedores instaló cajas nido para lechuzas. ¿Qué práctica podría arruinar ese control?","options":["Instalar perchas","Usar rodenticidas anticoagulantes sin protección","Dejar franjas de pasto nativo","Mantener árboles viejos"],"correct_index":1,"explanation":"Las lechuzas comen los roedores envenenados y se intoxican: envenenamiento secundario."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m10-s3', 'm10-s3', 'Aves del Campo Chileno', '[{"heading":"Granívoras y frugívoras","body":["El chincol (Zonotrichia capensis), la diuca (Diuca diuca) y la tórtola (Zenaida auriculata) comen semillas y pueden dañar siembras y granos. El tordo (Curaeus curaeus), negro y gregario, forma bandadas en maizales y frutales.","El zorzal (Turdus falcklandii) come lombrices e insectos, pero también fruta madura como cerezas y arándanos. La rara (Phytotoma rara) corta brotes, yemas y hojas tiernas de frutales y hortalizas."]},{"heading":"Aliadas del agricultor","body":["Golondrinas, cachuditos y rayaditos consumen grandes cantidades de insectos. La loica (Leistes loyca) y el queltehue (Vanellus chilensis) comen larvas e insectos del suelo en praderas; la garza boyera (Bubulcus ibis) sigue al ganado para atrapar los insectos que este levanta.","El picaflor chico (Sephanoides sephaniodes) poliniza muchas plantas nativas del sur."]},{"heading":"Especies introducidas","body":["El gorrión (Passer domesticus) llegó desde Europa y se asocia a construcciones humanas. La codorniz (Callipepla californica) fue introducida desde Norteamérica y hoy es especie de caza.","La cotorra argentina (Myiopsitta monachus) es una especie invasora: forma grandes nidos comunales de palitos en árboles y postes de electricidad, y daña frutales y granos."]}]'::jsonb, null, null, '[{"id":"m10-s3-cp1","timestamp_seconds":140,"prompt":"Se encuentran grandes nidos comunales de palitos en postes del tendido eléctrico cerca de un huerto. ¿Qué ave los construye?","options":["Tordo","Cotorra argentina","Zorzal","Queltehue"],"correct_index":1,"explanation":"La cotorra argentina, especie invasora, es la única de estas aves que construye grandes nidos comunales de palitos."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m10-s4', 'm10-s4', 'Humedales y Aves Acuáticas', '[{"heading":"Por qué importan los humedales","body":["Los humedales regulan el agua (amortiguan crecidas y recargan acuíferos), filtran sedimentos y nutrientes que escurren de los campos y albergan una enorme biodiversidad.","La Convención de Ramsar protege humedales de importancia internacional. El primer sitio Ramsar de Chile fue el Santuario de la Naturaleza Carlos Anwandter, en el río Cruces de Valdivia."]},{"heading":"Aves acuáticas","body":["El cisne de cuello negro (Cygnus melancoryphus) se alimenta de plantas acuáticas como el luchecillo; su población del río Cruces colapsó en 2004 cuando esa vegetación desapareció por un cambio en la calidad del agua.","Las taguas (Fulica) nadan y bucean entre la vegetación; el pato jergón grande (Anas georgica) es el pato más común; la garza grande (Ardea alba) y el huairavo (Nycticorax nycticorax) cazan peces y anfibios. En los salares del altiplano habita el flamenco chileno."]},{"heading":"Humedales y agricultura","body":["El drenaje de vegas y ñadis, la extracción de agua y la escorrentía con fertilizantes (eutrofización) son las principales amenazas que vienen del uso agrícola.","Franjas de vegetación ribereña, aplicaciones cuidadosas de agroquímicos lejos de cursos de agua y el respeto de las áreas protegidas ayudan a conservarlos."]}]'::jsonb, null, null, '[{"id":"m10-s4-cp1","timestamp_seconds":125,"prompt":"¿Qué provocó el colapso de la población de cisnes de cuello negro del río Cruces en 2004?","options":["La caza ilegal","La desaparición del luchecillo, su alimento, por un cambio en la calidad del agua","Una ola de frío","La llegada de un depredador introducido"],"correct_index":1,"explanation":"El cisne depende del luchecillo (Egeria densa). Su desaparición dejó a la población sin alimento, con muertes y migración masiva."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m10-s5', 'm10-s5', 'Manejo de Daño por Aves y Conservación', '[{"heading":"El marco legal","body":["En Chile la Ley de Caza (Ley 19.473) y su reglamento definen qué especies se pueden cazar, cuáles están protegidas y cuáles se consideran dañinas. El SAG fiscaliza y otorga permisos especiales cuando una especie protegida causa daños graves.","Cazar, capturar o destruir nidos de especies protegidas sin autorización es un delito, aunque el ave esté dañando un cultivo."]},{"heading":"Loros nativos","body":["El choroy (Enicognathus leptorhynchus) es un loro endémico de los bosques del centro-sur: come semillas de araucaria, cereales y fruta, y puede dañar siembras y huertos. El tricahue (Cyanoliseus patagonus) es el loro más grande de Chile y está amenazado por la pérdida de hábitat y la extracción de polluelos.","Ambos son ejemplos de conflicto entre producción y conservación: la solución pasa por métodos de exclusión y ahuyentamiento, no por eliminarlos."]},{"heading":"Métodos de manejo","body":["Exclusión: mallas antipájaros sobre cerezos, arándanos o viñas; es el método más eficaz y protege también contra granizo.","Ahuyentamiento: cañones de gas, señales acústicas de alarma, cintas reflectantes, láser y cetrería con halcones. Las aves se acostumbran rápido, por eso hay que rotar métodos y moverlos de lugar.","Manejo del cultivo: sembrar a la profundidad correcta, cosechar a tiempo y evitar dejar grano expuesto reducen la atracción para las bandadas."]}]'::jsonb, null, null, '[{"id":"m10-s5-cp1","timestamp_seconds":150,"prompt":"Una bandada de choroyes daña un huerto de cerezos. ¿Cuál es la acción correcta?","options":["Cazarlos: están dañando el cultivo","Usar mallas y ahuyentadores, y consultar al SAG si el daño es grave","Envenenar el agua","Destruir sus nidos en el bosque"],"correct_index":1,"explanation":"El choroy es una especie protegida: se maneja con exclusión y ahuyentamiento; el SAG puede autorizar medidas especiales."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m11-s1', 'm11-s1', 'Qué es un Hongo', '[{"heading":"Un reino propio","body":["Los hongos no son plantas: no hacen fotosíntesis y su pared celular es de quitina, no de celulosa. Son heterótrofos que se alimentan por absorción: secretan enzimas al medio y absorben las moléculas digeridas.","Según cómo obtienen su alimento son saprófitos (descomponen materia muerta), parásitos (viven de un hospedero vivo) o simbiontes mutualistas (micorrizas, líquenes)."]},{"heading":"Hifas y micelio","body":["El cuerpo de la mayoría de los hongos es un conjunto de filamentos llamados hifas, que en conjunto forman el micelio. Las hifas pueden ser tabicadas (con septos) o cenocíticas (sin tabiques).","Lo que llamamos \"callampa\" o seta es solo el cuerpo fructífero, la estructura que produce esporas; el micelio vive bajo el suelo o dentro de la madera y puede ocupar grandes superficies.","Las levaduras son hongos unicelulares, como Saccharomyces cerevisiae, que fermenta el pan, la cerveza y el vino."]},{"heading":"Grandes grupos","body":["Los Ascomycota forman esporas dentro de sacos (ascos): incluyen levaduras, Botrytis, Penicillium, oídios y morchellas. Los Basidiomycota forman esporas en basidios: la mayoría de las setas con sombrero, royas y carbones.","Los oomicetos, como Phytophthora y los mildiús, parecen hongos pero pertenecen a otro grupo (Stramenopila): su pared es de celulosa y por eso responden a fungicidas específicos."]}]'::jsonb, null, null, '[{"id":"m11-s1-cp1","timestamp_seconds":120,"prompt":"¿Por qué un fungicida eficaz contra Botrytis puede no controlar a Phytophthora?","options":["Porque Phytophthora es una bacteria","Porque Phytophthora es un oomiceto, con pared de celulosa y otra biología","Porque Phytophthora es un virus","Porque Botrytis vive en el suelo"],"correct_index":1,"explanation":"Los oomicetos no son hongos verdaderos: su pared de celulosa y su metabolismo distinto exigen fungicidas específicos (como fosfitos o metalaxil)."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m11-s2', 'm11-s2', 'Reproducción de los Hongos', '[{"heading":"Esporas","body":["Los hongos se dispersan por esporas que viajan con el viento, el agua, los insectos o las herramientas. Las asexuales, como los conidios, se producen en enormes cantidades y causan las epidemias durante la temporada.","Las sexuales (ascosporas, basidiosporas) aportan variabilidad genética, lo que favorece la aparición de resistencia a fungicidas y de nuevas razas."]},{"heading":"Ciclos de vida","body":["La infección primaria inicia la enfermedad a partir del inóculo que sobrevivió el invierno; las infecciones secundarias la multiplican durante la temporada. Una enfermedad policíclica, como el oídio o la botritis, tiene muchos ciclos por temporada.","La venturia del manzano (Venturia inaequalis) sobrevive en hojas caídas y libera ascosporas en primavera con lluvia: eliminar o triturar la hoja caída reduce el inóculo primario."]},{"heading":"Estructuras de supervivencia","body":["Los esclerocios son masas compactas de micelio que sobreviven años en el suelo (Sclerotinia, Sclerotium). Las clamidosporas son esporas de pared gruesa que resisten condiciones adversas (Fusarium).","Por eso la rotación de cultivos, la sanidad de los restos de cosecha y la semilla limpia son tan importantes como los fungicidas."]}]'::jsonb, null, null, '[{"id":"m11-s2-cp1","timestamp_seconds":135,"prompt":"En un huerto de manzanos con venturia, ¿qué práctica reduce el inóculo primario de la próxima primavera?","options":["Regar más en verano","Triturar o eliminar la hoja caída en otoño","Podar en verano","Aplicar nitrógeno en invierno"],"correct_index":1,"explanation":"Venturia inverna en la hoja caída y desde ahí libera las ascosporas que inician las infecciones de primavera."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m11-s3', 'm11-s3', 'Hongos Benéficos para la Agricultura', '[{"heading":"Micorrizas","body":["Las micorrizas son asociaciones entre hongos y raíces. Las arbusculares (Glomeromycota) colonizan el interior de las raíces de la mayoría de los cultivos y aumentan la absorción de fósforo, agua y micronutrientes; a cambio reciben azúcares.","Las ectomicorrizas envuelven las raíces de pinos, robles y Nothofagus, y muchas producen setas comestibles. Las ericoides acompañan a arándanos y cranberry.","La labranza intensa, el suelo desnudo y el exceso de fósforo soluble reducen las micorrizas."]},{"heading":"Biocontroladores","body":["Trichoderma compite por espacio y nutrientes, parasita a otros hongos (micoparasitismo) y produce antibióticos: se usa contra Botrytis, Rhizoctonia y pudriciones de raíz y cuello.","Los hongos entomopatógenos, como Beauveria bassiana y Metarhizium, infectan insectos a través de la cutícula y se usan como bioinsecticidas."]},{"heading":"Descomponedores","body":["Los hongos saprófitos son los principales descomponedores de la lignina y la celulosa: reciclan nutrientes y forman humus. Sin ellos los rastrojos se acumularían por décadas.","Las hifas y la glomalina de las micorrizas pegan las partículas del suelo y estabilizan los agregados."]}]'::jsonb, null, null, '[{"id":"m11-s3-cp1","timestamp_seconds":145,"prompt":"Un productor aplica dosis muy altas de fósforo soluble cada año. ¿Qué efecto puede tener sobre las micorrizas?","options":["Las multiplica","Las reduce, porque la planta deja de \"pagarles\" con azúcares","Las convierte en patógenos","No tiene efecto"],"correct_index":1,"explanation":"Con fósforo abundante la planta invierte menos carbono en la simbiosis y la colonización micorrícica cae."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m11-s4', 'm11-s4', 'Enfermedades Fúngicas de los Cultivos', '[{"heading":"El triángulo de la enfermedad","body":["Una enfermedad ocurre cuando coinciden un hospedero susceptible, un patógeno virulento y un ambiente favorable, durante el tiempo suficiente. El manejo actúa sobre los tres lados: variedades resistentes, menos inóculo y menos condiciones favorables.","Muchos hongos necesitan agua libre sobre la hoja por varias horas para infectar: por eso los modelos de pronóstico usan horas de mojado y temperatura."]},{"heading":"Enfermedades clave","body":["Botrytis cinerea (pudrición gris) ataca flores y frutos de uva, frutilla, frambuesa y arándano, con alta humedad. El oídio forma un polvo blanco sobre hojas y bayas y, a diferencia de la mayoría, no necesita agua libre: le basta la humedad ambiental.","Las royas forman pústulas de color óxido (trigo, poroto, ajo); algunas necesitan dos hospederos distintos para completar su ciclo. Fusarium y Verticillium tapan los vasos del xilema y causan marchitez."]},{"heading":"Manejo","body":["Los fungicidas preventivos (de contacto, como cobre o captan) protegen la superficie antes de la infección; los sistémicos penetran y pueden detener infecciones recientes, pero tienen alto riesgo de resistencia si se repite el mismo modo de acción.","La clasificación FRAC agrupa los fungicidas por modo de acción para planificar rotaciones. La poda que ventila, la eliminación de restos enfermos y el riego que no moja el follaje completan el manejo integrado."]}]'::jsonb, null, null, '[{"id":"m11-s4-cp1","timestamp_seconds":155,"prompt":"Una viña tiene polvo blanco sobre hojas y racimos en un verano seco, sin lluvias. ¿Qué enfermedad es más probable?","options":["Botrytis","Oídio","Mildiú","Roya"],"correct_index":1,"explanation":"El oídio forma un micelio blanco superficial y no necesita agua libre para infectar: prospera en veranos secos."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m11-s5', 'm11-s5', 'Hongos Silvestres Comestibles y Tóxicos', '[{"heading":"Hongos comestibles nativos","body":["El digüeñe (Cyttaria espinosae) es un hongo parásito del roble y el hualle: forma cuerpos fructíferos anaranjados con alvéolos en primavera. El changle (Ramaria flava) es coraloide y amarillo, y crece en bosques de Nothofagus en otoño.","El loyo (Boletus loyo) es un boleto con poros en vez de láminas; el gargal (Grifola gargal) crece sobre troncos. La recolección de estas especies es un saber tradicional del pueblo mapuche y del campesinado del sur."]},{"heading":"Hongos de plantaciones","body":["En las plantaciones de pino crecen Suillus luteus (callampa de pino, con poros y sombrero viscoso) y Lactarius deliciosus (exuda un látex anaranjado). Ambos son ectomicorrícicos y llegaron con los pinos.","La morchella (Morchella), de sombrero alveolado, se recolecta y exporta deshidratada."]},{"heading":"Especies tóxicas","body":["Amanita phalloides, introducida en Chile junto a robles y encinos europeos, contiene amatoxinas que destruyen el hígado; los síntomas aparecen 6 a 24 horas después, cuando el daño ya avanzó. Amanita muscaria, de sombrero rojo con verrugas blancas, también es tóxica.","Las Amanita tienen láminas blancas, anillo y una volva (bolsa) en la base del pie: si el pie no se desentierra, la volva queda oculta. La regla es simple: nunca consumir un hongo silvestre sin identificación segura por un experto. No existen \"pruebas caseras\" (plata, ajo, animales) que indiquen si un hongo es comestible."]}]'::jsonb, null, null, '[{"id":"m11-s5-cp1","timestamp_seconds":165,"prompt":"Una seta tiene láminas blancas, anillo y una bolsa en la base del pie. ¿Qué conviene concluir?","options":["Es un digüeñe comestible","Tiene rasgos de Amanita: no consumir","Es una callampa de pino","Si no tiene mal olor, es comestible"],"correct_index":1,"explanation":"Láminas blancas, anillo y volva son rasgos típicos del género Amanita, que incluye especies mortales como A. phalloides."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m12-s1', 'm12-s1', 'Sistemas de Producción Avícola', '[{"heading":"Carne y huevo","body":["La avicultura moderna usa híbridos comerciales seleccionados para un solo propósito. Los broilers (pollos de carne), como Ross o Cobb, alcanzan unos 2,5 a 3 kg en alrededor de 40-42 días. Las ponedoras comerciales, blancas o rojas (Hy-Line, Lohmann), producen más de 300 huevos por año.","Las razas de doble propósito (Plymouth Rock, Rhode Island Red) y la gallina mapuche de huevos azules (collonca) se crían en sistemas campesinos de traspatio."]},{"heading":"Sistemas productivos","body":["Los broilers se crían en galpones sobre cama (viruta o paja). Las ponedoras se crían en jaulas convencionales, jaulas enriquecidas, sistemas libres de jaula en piso o aviario, o al aire libre con acceso a pastoreo (free range).","La tendencia del mercado y de la regulación es hacia sistemas libres de jaula, que mejoran el bienestar pero exigen más espacio y manejo sanitario."]},{"heading":"Índices productivos","body":["En carne, el índice clave es la conversión alimenticia: kilos de alimento por kilo de peso vivo, cercana a 1,5-1,7 en broilers modernos. También se miden ganancia diaria, mortalidad y uniformidad del lote.","En postura se miden el porcentaje de postura (huevos por gallina por día), el peso del huevo, la calidad de cáscara y los kilos de alimento por docena de huevos."]}]'::jsonb, null, null, '[{"id":"m12-s1-cp1","timestamp_seconds":115,"prompt":"Un lote de broilers consumió 4.200 kg de alimento y produjo 2.800 kg de peso vivo. ¿Cuál es la conversión alimenticia?","options":["0,67","1,5","2,8","4,2"],"correct_index":1,"explanation":"Conversión = alimento / peso producido = 4.200 / 2.800 = 1,5 kg de alimento por kg de peso vivo."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m12-s2', 'm12-s2', 'Nutrición de Aves', '[{"heading":"Energía y proteína","body":["Las aves comen principalmente para cubrir su requerimiento de energía, que se expresa como energía metabolizable (kcal/kg). El maíz es la principal fuente energética y la harina de soya, la principal fuente de proteína.","Más que la proteína total importan los aminoácidos esenciales: la metionina es el primer limitante en dietas maíz-soya, seguida de la lisina. Se agregan en forma sintética para no sobrecargar de proteína la dieta."]},{"heading":"Dietas por etapa","body":["Los broilers reciben dietas de inicio, crecimiento y terminación, con proteína decreciente a medida que crecen. Las ponedoras pasan por recría y luego postura.","La ponedora necesita mucho calcio (alrededor de 3,5 a 4,5 % de la dieta), idealmente con parte en partículas gruesas (conchilla), que se disuelven lentamente durante la noche, cuando se forma la cáscara."]},{"heading":"Agua y calidad del alimento","body":["Las aves beben aproximadamente el doble de agua que el alimento que consumen, y más con calor. Una caída del consumo de agua suele ser la primera señal de enfermedad.","Las micotoxinas (aflatoxinas, por ejemplo) de granos mal almacenados dañan el hígado, la inmunidad y la producción: el grano debe guardarse seco y se usan secuestrantes."]}]'::jsonb, null, null, '[{"id":"m12-s2-cp1","timestamp_seconds":140,"prompt":"Un lote de ponedoras produce huevos de cáscara delgada que se quiebran. ¿Qué revisar primero en la dieta?","options":["La metionina","El calcio y su granulometría, junto con la vitamina D₃","La energía metabolizable","La fibra"],"correct_index":1,"explanation":"La cáscara es carbonato de calcio: hay que revisar el nivel de calcio, la proporción de partículas gruesas y la vitamina D₃, necesaria para absorberlo."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m12-s3', 'm12-s3', 'Manejo Ambiental del Galpón', '[{"heading":"Crianza y temperatura","body":["Los pollitos no regulan bien su temperatura durante las primeras semanas: necesitan cerca de 32-35 °C al nivel del ave en la primera semana, y luego unos 3 °C menos por semana hasta llegar a 20-22 °C.","El comportamiento indica si la temperatura es correcta: amontonados bajo la fuente de calor tienen frío; alejados, jadeando y con alas abiertas tienen calor; repartidos de forma pareja están cómodos."]},{"heading":"Ventilación y amoníaco","body":["La ventilación saca humedad, calor, CO₂ y amoníaco. El amoníaco se forma en una cama húmeda a partir de las deyecciones: sobre unos 20-25 ppm irrita ojos y vías respiratorias y favorece enfermedades.","Una cama húmeda y apelmazada además causa lesiones en las patas (pododermatitis) y en la pechuga. Bebederos sin fugas, buena ventilación y densidades adecuadas la mantienen seca."]},{"heading":"Luz","body":["En ponedoras, el fotoperiodo controla la madurez sexual y la postura: se cría con días cortos y constantes, y al llegar a la edad de postura se estimula con aumentos graduales hasta unas 16 horas de luz. Nunca se debe reducir la luz durante la postura.","En broilers, programas con algunas horas de oscuridad mejoran la salud de las patas y el bienestar."]}]'::jsonb, null, null, '[{"id":"m12-s3-cp1","timestamp_seconds":150,"prompt":"Al entrar al galpón de recría los pollitos están amontonados bajo las criadoras. ¿Qué indica?","options":["Que tienen calor","Que tienen frío: falta temperatura","Que tienen hambre","Que el amoníaco es bajo"],"correct_index":1,"explanation":"Los pollitos se agrupan bajo la fuente de calor cuando la temperatura es insuficiente. Si tuvieran calor, se alejarían y jadearían."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m12-s4', 'm12-s4', 'Sanidad Avícola', '[{"heading":"Enfermedades de importancia","body":["La influenza aviar de alta patogenicidad y la enfermedad de Newcastle son de denuncia obligatoria al SAG: causan alta mortalidad y restricciones al comercio. Las aves silvestres migratorias pueden introducir la influenza aviar, como ocurrió en Chile en 2022-2023.","La enfermedad de Marek, causada por un herpesvirus, produce tumores y parálisis; se vacuna en la incubadora o al día de edad. La bronquitis infecciosa y el Gumboro (bursitis infecciosa) también se previenen con vacunas."]},{"heading":"Coccidiosis","body":["La coccidiosis la causan protozoos del género Eimeria, que dañan el intestino: diarrea, a veces con sangre, y mala conversión. Prospera en camas húmedas.","Se controla con anticoccidiales en el alimento, vacunas y, sobre todo, manteniendo la cama seca."]},{"heading":"Bioseguridad","body":["Es el conjunto de medidas para que los patógenos no entren ni salgan del plantel: cercos, control de visitas, cambio de ropa y calzado, pediluvios, desinfección de vehículos, control de roedores y aves silvestres, y agua potable.","El sistema \"todo dentro, todo fuera\" cría lotes de una sola edad, y entre lotes se limpia, desinfecta y deja un vacío sanitario. Mezclar edades mantiene los patógenos circulando."]}]'::jsonb, null, null, '[{"id":"m12-s4-cp1","timestamp_seconds":160,"prompt":"En un plantel aparece mortalidad súbita y alta con signos respiratorios y nerviosos. ¿Qué corresponde?","options":["Esperar una semana","Denunciar de inmediato al SAG y aislar el plantel","Vender las aves rápido","Aplicar un anticoccidial"],"correct_index":1,"explanation":"Mortalidad alta con signos respiratorios y nerviosos sugiere influenza aviar o Newcastle, enfermedades de denuncia obligatoria."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m12-s5', 'm12-s5', 'Producción de Huevos y Bienestar Animal', '[{"heading":"Formación y calidad del huevo","body":["El huevo tarda unas 24-26 horas en formarse en el oviducto, de las cuales cerca de 20 corresponden a la cáscara en el útero. Por eso la gallina pone aproximadamente un huevo al día.","La calidad interna se mide en unidades Haugh (altura de la clara densa en relación al peso): baja con la edad del huevo y con temperaturas altas de almacenaje. El color de la yema depende de los pigmentos (xantofilas) de la dieta, no del valor nutritivo.","El color de la cáscara depende de la línea genética: no cambia el valor nutritivo del huevo."]},{"heading":"Muda y ciclo productivo","body":["Después de unas 70-80 semanas la postura y la calidad de cáscara bajan. La muda natural renueva plumas y el aparato reproductor; las mudas inducidas por ayuno prolongado están cuestionadas o prohibidas por razones de bienestar."]},{"heading":"Bienestar animal","body":["Las cinco libertades: libres de hambre y sed; de incomodidad; de dolor, lesiones y enfermedad; libres para expresar su comportamiento normal; y libres de miedo y angustia.","El picaje (las aves se picotean plumas y piel) aparece con alta densidad, exceso de luz, dietas pobres en aminoácidos azufrados, aburrimiento o falta de material para escarbar. Se previene con enriquecimiento ambiental, perchas, nidos, baños de polvo y dietas balanceadas."]}]'::jsonb, null, null, '[{"id":"m12-s5-cp1","timestamp_seconds":155,"prompt":"Un lote libre de jaula sufre picaje creciente. ¿Qué combinación ayuda a prevenirlo?","options":["Más luz y más densidad","Enriquecimiento ambiental, menos densidad y dieta con suficiente metionina","Reducir el agua","Quitar las perchas"],"correct_index":1,"explanation":"El picaje se relaciona con estrés, aburrimiento y dietas pobres en aminoácidos azufrados. El enriquecimiento y una densidad adecuada lo reducen."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m13-s1', 'm13-s1', 'Sistemas de Producción Caprina', '[{"heading":"La caprinocultura en Chile","body":["La mayor parte de las cabras de Chile está en el secano del Norte Chico, con la región de Coquimbo como principal zona caprina. Predomina la crianza campesina de cabras criollas, rústicas y adaptadas a la escasez de forraje.","Muchos crianceros practican la trashumancia: en verano suben con el rebaño a las veranadas cordilleranas y en invierno vuelven a los valles y al secano costero."]},{"heading":"Razas","body":["Lecheras: Saanen (blanca, la más productiva), Alpina, Toggenburg y Anglo-Nubian (orejas largas y caídas, leche con más grasa). Carne: Boer, de origen sudafricano, con gran desarrollo muscular.","El cruzamiento de cabras criollas con machos de razas lecheras o Boer aumenta la producción, pero los cruzas exigen mejor alimentación y sanidad que la criolla."]},{"heading":"Ovinos y otros rumiantes menores","body":["Los ovinos dominan en la Patagonia (Magallanes, con razas como Corriedale y Merino para lana y carne) y en el centro-sur con razas de carne como Suffolk.","Cabras y ovejas difieren en su conducta alimentaria: la oveja pastorea pasto bajo, mientras que la cabra ramonea hojas y brotes de arbustos, lo que le permite aprovechar matorrales que otras especies no usan."]}]'::jsonb, null, null, '[{"id":"m13-s1-cp1","timestamp_seconds":120,"prompt":"¿Qué es la trashumancia en la crianza caprina del Norte Chico?","options":["La venta de cabras en ferias","El traslado estacional del rebaño a veranadas cordilleranas","Un tipo de queso","La crianza en galpones cerrados"],"correct_index":1,"explanation":"Los crianceros suben con el rebaño a las veranadas de la cordillera en verano, donde hay forraje, y bajan en invierno."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m13-s2', 'm13-s2', 'Nutrición de Rumiantes Menores', '[{"heading":"El rumen","body":["Los rumiantes tienen un estómago de cuatro compartimentos: rumen, retículo, omaso y abomaso (cuajar, el estómago \"verdadero\"). En el rumen, bacterias, protozoos y hongos fermentan la fibra y producen ácidos grasos volátiles, la principal fuente de energía del animal.","Los microorganismos también sintetizan proteína microbiana a partir del nitrógeno de la dieta, incluso de fuentes no proteicas como la urea, y vitaminas del complejo B."]},{"heading":"Fibra y acidosis","body":["La fibra estimula la rumia y la saliva, que contiene bicarbonato y amortigua el pH del rumen. Una dieta con mucho grano y poca fibra fermenta rápido, acumula ácido láctico y baja el pH bajo 5,5: es la acidosis ruminal, que causa diarrea, cojeras e incluso la muerte.","Los cambios de dieta deben hacerse de forma gradual, durante una o dos semanas, para que la flora ruminal se adapte."]},{"heading":"Alimentación en el secano","body":["En el secano la disponibilidad de forraje sigue a las lluvias: abundante en invierno-primavera y escasa en verano-otoño. Las estrategias incluyen guardar heno, usar arbustos forrajeros como el atriplex, rastrojos de cultivos y suplementar en los periodos críticos.","Los requerimientos más altos están en el último tercio de la gestación y en la lactancia: una cabra mal alimentada en esos momentos tiene crías débiles y poca leche."]}]'::jsonb, null, null, '[{"id":"m13-s2-cp1","timestamp_seconds":135,"prompt":"Un criancero cambió de golpe a sus cabras de pastoreo a una dieta con mucha avena grano. Varias tienen diarrea y están decaídas. ¿Qué ocurrió?","options":["Deficiencia de calcio","Acidosis ruminal por exceso de grano y cambio brusco","Exceso de fibra","Falta de agua"],"correct_index":1,"explanation":"El grano fermenta rápido, acumula ácido láctico y baja el pH del rumen. El cambio brusco no dejó adaptarse a la flora ruminal."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m13-s3', 'm13-s3', 'Reproducción Caprina', '[{"heading":"Estacionalidad","body":["La cabra es una reproductora estacional de días cortos: su actividad sexual se concentra en otoño, cuando los días se acortan. Por eso la mayoría de los partos ocurre a fines de invierno y en primavera, cuando hay más forraje.","El ciclo estral dura unos 21 días y el celo de 24 a 36 horas; la gestación dura alrededor de 150 días (cinco meses)."]},{"heading":"Efecto macho y manejo","body":["Si el macho se mantiene separado de las hembras y luego se reintroduce al comienzo de la temporada, su olor estimula la ovulación y sincroniza los celos: es el efecto macho. También se usan tratamientos hormonales y programas de luz para producir fuera de temporada.","Un macho puede servir a unas 30 a 50 hembras en monta natural. Conviene registrar los encastes para conocer las fechas de parto."]},{"heading":"Parto y calostro","body":["El cabrito debe tomar calostro en sus primeras horas de vida: es su única fuente de anticuerpos, porque la placenta no los transfiere. La capacidad del intestino para absorberlos cae rápidamente después de las primeras 12 a 24 horas.","En lecherías los cabritos se separan y se crían con calostro tratado y sustituto lácteo, una práctica que también ayuda a cortar la transmisión de la artritis encefalitis caprina."]}]'::jsonb, null, null, '[{"id":"m13-s3-cp1","timestamp_seconds":145,"prompt":"Un cabrito nacido hace 30 horas no ha tomado calostro. ¿Cuál es el problema principal?","options":["Ninguno: lo puede tomar cuando quiera","Su intestino ya absorbe muy pocos anticuerpos: queda sin defensas","Tendrá exceso de grasa","Crecerá más rápido"],"correct_index":1,"explanation":"La absorción de anticuerpos del calostro cae mucho tras las primeras 12-24 horas: el cabrito queda con baja inmunidad."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m13-s4', 'm13-s4', 'Sanidad de Cabras y Ovejas', '[{"heading":"Parásitos gastrointestinales","body":["Haemonchus contortus es un nematodo que vive en el abomaso y se alimenta de sangre: causa anemia, edema submandibular (\"papada de botella\") y muerte, sobre todo en primaveras húmedas.","El método FAMACHA compara el color de la mucosa del ojo con una tarjeta: solo se desparasita a los animales pálidos. Así se reduce el uso de antiparasitarios y se frena la resistencia, que ya es un problema serio."]},{"heading":"Enfermedades infecciosas","body":["La artritis encefalitis caprina (CAE) es un lentivirus que se transmite sobre todo por el calostro y la leche: causa artritis, mastitis indurada y encefalitis en cabritos. No tiene cura; se controla con diagnóstico y separación de crías.","La linfadenitis caseosa (Corynebacterium pseudotuberculosis) forma abscesos en los ganglios con pus espeso; se contagia por heridas de esquila o descorne y por el pus de abscesos que se rompen.","La brucelosis caprina (Brucella melitensis) causa abortos y es una zoonosis grave, transmitida a las personas por leche y quesos sin pasteurizar: es de denuncia obligatoria al SAG."]},{"heading":"Mastitis y manejo sanitario","body":["La mastitis es la inflamación de la ubre, casi siempre bacteriana. El California Mastitis Test (CMT) detecta mastitis subclínica en la leche. La higiene de la ordeña y el sellado de pezones la previenen.","Un calendario sanitario incluye vacunación contra clostridiales (enterotoxemia), control de parásitos con FAMACHA, cuarentena de animales nuevos y despezuñe periódico."]}]'::jsonb, null, null, '[{"id":"m13-s4-cp1","timestamp_seconds":155,"prompt":"Varias cabras tienen la mucosa del ojo muy pálida y edema bajo la mandíbula en una primavera húmeda. ¿Qué es lo más probable?","options":["Linfadenitis caseosa","Haemonchosis (Haemonchus contortus)","Acidosis ruminal","Mastitis"],"correct_index":1,"explanation":"Mucosas pálidas (anemia) y \"papada de botella\" son típicas de Haemonchus, que se alimenta de sangre en el abomaso."}]'::jsonb)
insert into public.codices (id, submodule_id, title, sections, video_url, video_duration_seconds, interactive_checkpoints) values ('codex-m13-s5', 'm13-s5', 'Leche y Quesos de Cabra', '[{"heading":"La leche de cabra","body":["Tiene glóbulos de grasa más pequeños que la de vaca y una proporción mayor de ácidos grasos de cadena media (caproico, caprílico y cáprico), responsables de su sabor característico.","Las cabras transforman casi todo el betacaroteno en vitamina A: por eso su leche y sus quesos son más blancos que los de vaca. Una cabra criolla produce poca leche en lactancias cortas; una Saanen bien alimentada puede producir varios litros diarios."]},{"heading":"Higiene y pasteurización","body":["La calidad se mide por el recuento de células somáticas (indicador de mastitis) y el recuento bacteriano. Una ordeña higiénica y el enfriamiento rápido de la leche son esenciales.","La pasteurización (por ejemplo, 72 °C por 15 segundos o 63 °C por 30 minutos) elimina patógenos como Brucella y Listeria. El queso de leche cruda es un riesgo real de brucelosis y listeriosis."]},{"heading":"Elaboración de quesos","body":["El queso se obtiene coagulando la caseína con cuajo (quimosina) o con acidez; luego se corta la cuajada, se desuera, se sala, se moldea, se prensa y, en algunos casos, se madura.","El queso de cabra fresco es tradicional en el Norte Chico. La formalización de queserías campesinas con resolución sanitaria y leche pasteurizada abre mercados formales y protege la salud de los consumidores."]}]'::jsonb, null, null, '[{"id":"m13-s5-cp1","timestamp_seconds":160,"prompt":"Una quesería campesina quiere vender quesos en el comercio formal. ¿Qué cambio es indispensable para la seguridad alimentaria?","options":["Usar leche cruda más fresca","Pasteurizar la leche y contar con resolución sanitaria","Agregar más sal","Madurar el queso al sol"],"correct_index":1,"explanation":"La pasteurización elimina patógenos como Brucella y Listeria, y la resolución sanitaria es requisito para vender en el comercio formal."}]'::jsonb)
insert into public.questions (id, module_id, submodule_id, prompt, correct_answer, distractors, is_boss_final, sort_order) values
  ('m1-s1-q1', 1, 'm1-s1', 'Según el USDA, ¿qué tamaño tienen las partículas de arcilla?', 'Menos de 0,002 mm', array['Entre 0,05 y 2 mm', 'Menos de 0,05 mm', 'Entre 0,002 y 0,05 mm']::text[], false, 1),
  ('m1-s1-q2', 1, 'm1-s1', '¿Para qué se agrega hexametafosfato de sodio en el método de Bouyoucos?', 'Para dispersar los agregados en partículas individuales', array['Para flocular la arcilla', 'Para eliminar la materia orgánica', 'Para acelerar la sedimentación de la arena']::text[], false, 2),
  ('m1-s1-q3', 1, 'm1-s1', '¿Qué propiedad del suelo prácticamente no cambia con el manejo agronómico?', 'La textura', array['La estructura', 'La densidad aparente', 'El contenido de materia orgánica']::text[], false, 3),
  ('m1-s1-q4', 1, 'm1-s1', '¿Qué tipo de estructura se asocia a suelos sódicos?', 'Columnar', array['Granular', 'Laminar', 'Grano simple']::text[], false, 4),
  ('m0-q14', 1, 'm1-s1', '¿En qué se diferencia un suelo salino de uno sódico?', 'Salino: alta CE; sódico: alto PSI que destruye la estructura', array['El salino retiene y el sódico repele agua', 'El sódico está en el sur y el salino en el norte', 'Son sinónimos']::text[], false, 5),
  ('m0-q1', 1, 'm1-s2', '¿Qué clase textural tiene la mayor Capacidad de Campo y el mayor Punto de Marchitez?', 'Arcillosa', array['Arenosa', 'Franca', 'Franco-limosa']::text[], false, 6),
  ('m1-s2-q1', 1, 'm1-s2', '¿A qué potencial mátrico se asocia habitualmente el Punto de Marchitez Permanente?', '−1.500 kPa (−15 bar)', array['−33 kPa (−1/3 bar)', '−10 kPa', '−100 kPa']::text[], false, 7),
  ('m1-s2-q2', 1, 'm1-s2', '¿Qué equipo de laboratorio se usa para construir la curva característica de humedad?', 'Ollas o placas de presión de Richards', array['Densímetro de Bouyoucos', 'Penetrómetro de cono', 'Cilindro infiltrómetro']::text[], false, 8),
  ('m1-s2-q3', 1, 'm1-s2', 'Con θCC = 30 %, θPMP = 14 % y raíces a 40 cm, ¿cuál es el agua disponible?', '64 mm', array['120 mm', '6,4 mm', '176 mm']::text[], false, 9),
  ('m1-s2-q4', 1, 'm1-s2', '¿Cuál es el rango de trabajo habitual de un tensiómetro?', 'De 0 a unos −80 kPa', array['De 0 a −1.500 kPa', 'De −100 a −1.500 kPa', 'Solo a saturación']::text[], false, 10),
  ('m0-q11', 1, 'm1-s3', '¿En qué se diferencian la densidad aparente y la densidad real del suelo?', 'La aparente incluye los poros; la real, solo los sólidos', array['La real cambia con la labranza', 'Ambas miden la materia orgánica', 'Son iguales']::text[], false, 11),
  ('m1-s3-q1', 1, 'm1-s3', 'Si Da = 1,325 g/cm³ y Dr = 2,65 g/cm³, ¿cuál es la porosidad total?', '50 %', array['25 %', '75 %', '13 %']::text[], false, 12),
  ('m1-s3-q2', 1, 'm1-s3', '¿Qué resistencia a la penetración se considera limitante para las raíces?', 'Alrededor de 2 MPa', array['Alrededor de 0,2 MPa', 'Alrededor de 20 MPa', 'Alrededor de 0,02 MPa']::text[], false, 13),
  ('m1-s3-q3', 1, 'm1-s3', '¿Cuándo es más susceptible a compactarse un suelo?', 'Con humedad cercana a capacidad de campo', array['Completamente seco', 'Congelado', 'En punto de marchitez']::text[], false, 14),
  ('m1-s3-q4', 1, 'm1-s3', '¿Qué es el "pie de arado"?', 'Una capa compactada bajo la profundidad habitual de labranza', array['El horizonte orgánico superficial', 'Una costra salina superficial', 'Una capa natural de grava']::text[], false, 15),
  ('m1-s4-q1', 1, 'm1-s4', '¿Cuál es el primer paso de la erosión hídrica?', 'El desprendimiento de partículas por el impacto de la gota', array['El depósito en el fondo del valle', 'La formación de cárcavas', 'La infiltración del agua']::text[], false, 16),
  ('m1-s4-q2', 1, 'm1-s4', 'En la USLE, ¿qué representa el factor K?', 'La erodabilidad del suelo', array['La erosividad de la lluvia', 'El largo y la inclinación de la pendiente', 'Las prácticas de conservación']::text[], false, 17),
  ('m1-s4-q3', 1, 'm1-s4', '¿Qué suelos suelen ser más erodables?', 'Limosos o de arenas muy finas con poca materia orgánica', array['Arcillosos bien floculados', 'Pedregosos', 'De arenas gruesas']::text[], false, 18),
  ('m1-s4-q4', 1, 'm1-s4', '¿Qué práctica reduce la erosión eólica?', 'Cortinas cortaviento y suelo cubierto', array['Quemar los rastrojos', 'Labrar en el sentido de la pendiente', 'Regar por surcos en pendiente']::text[], false, 19),
  ('m1-s4-q5', 1, 'm1-s4', '¿Qué distingue a una cárcava de un surco de erosión?', 'Es tan profunda que la labranza normal no la borra ni la cruza', array['Solo se forma con viento', 'Es una pérdida pareja de una capa delgada', 'Aparece solo en suelos arcillosos']::text[], false, 20),
  ('m0-q21', 1, 'm1-s5', '¿Qué arcillas amorfas dominan en los Trumaos?', 'Alofana e Imogolita', array['Montmorillonita y Caolinita', 'Ilita y Vermiculita', 'Cuarzo']::text[], false, 21),
