  ('m2-s3-q1', 2, 'm2-s3', '¿En qué hojas aparece primero la deficiencia de nitrógeno?', 'En las hojas viejas', array['En las hojas nuevas', 'Solo en los frutos', 'En la raíz']::text[], false, 11),
  ('m2-s3-q2', 2, 'm2-s3', '¿Cómo llega principalmente el fósforo hasta la raíz?', 'Por difusión, a muy corta distancia', array['Por flujo masal con el agua', 'Por intercepción de lluvia', 'Por volatilización']::text[], false, 12),
  ('m2-s3-q3', 2, 'm2-s3', '¿Qué proceso pierde N como N₂ y N₂O en suelos saturados?', 'Desnitrificación', array['Nitrificación', 'Mineralización', 'Fijación simbiótica']::text[], false, 13),
  ('m2-s3-q4', 2, 'm2-s3', '¿Qué síntoma es típico de deficiencia de potasio?', 'Necrosis en el borde de hojas viejas', array['Clorosis intervenal en brotes nuevos', 'Hojas moradas en plántulas', 'Muerte del ápice de raíces']::text[], false, 14),
  ('m2-s3-q5', 2, 'm2-s3', '¿Por qué los Andisoles exigen dosis altas de fósforo?', 'La alofana fija el fosfato con mucha fuerza', array['Su pH alcalino precipita el fosfato', 'Las lluvias lixivian todo el fósforo', 'Su materia orgánica consume el fósforo']::text[], false, 15),
  ('m2-s4-q1', 2, 'm2-s4', '¿Qué desorden de la manzana se asocia a falta de calcio en el fruto?', 'Bitter pit', array['Russet', 'Golpe de sol', 'Corazón acuoso']::text[], false, 16),
